window.QURAN_COMMANDS_DATA = {"version": "2.0.0", "title": "Divine Commands & Injunctions for Human Living (احکامِ الٰہی و طرزِ زندگی)", "subtitle": "The Quranic Blueprint for Human Flourishing, Health, Ethics & Social Harmony", "total_count": 80, "categories": [{"id": "health", "title_ur": "صحت، غذا اور طہارت", "title_en": "Health, Nutrition & Cleanliness", "icon": "🥗", "color": "#10b981", "description_ur": "پاکیزہ حلال خوراک، شراب و حرام سے اجتناب، صفائی، غسل، اعتدال اور جان کے تحفظ کے احکام۔"}, {"id": "speech", "title_ur": "گفتگو، لہجہ اور آدابِ کلام", "title_en": "Speech, Tone & Gentle Conversation", "icon": "🗣️", "color": "#38bdf8", "description_ur": "نرم لہجہ، آواز نیچی رکھنا، سچی گفتگو، لغو و بیہودگی سے دوری اور شائستہ کلام کے احکام۔"}, {"id": "compassion", "title_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "title_en": "Compassion, Charity & Feeding the Vulnerable", "icon": "🍲", "color": "#f59e0b", "description_ur": "بھوکوں کو کھانا کھلانا، یتیموں کی دستگیری، سوالی کو نہ جھڑکنا اور احسان جتلائے بغیر انفاق۔"}, {"id": "social_peace", "title_ur": "معاشرتی امن، پردہ داری اور اخوت", "title_en": "Social Peace, Privacy & Anti-Toxicity", "icon": "🤝", "color": "#a855f7", "description_ur": "غیبت، تجسس، بدگمانی، تمسخر سے اجتناب، صلح جوئی، سلام کا جواب اور گھروں میں اجازت کے احکام۔"}, {"id": "mental_peace", "title_ur": "ذہنی سکون، صبر اور امید", "title_en": "Mental Peace, Emotional Resilience & Patience", "icon": "🧠", "color": "#06b6d4", "description_ur": "صبر و نماز سے مدد، مایوسی سے ممانعت، غصہ ضبط کرنا، توکل اور دل کے اطمینان کے اصول۔"}, {"id": "finance", "title_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "title_en": "Financial Ethics, Honest Commerce & Fair Dealing", "icon": "⚖️", "color": "#eab308", "description_ur": "پورا ناپ تول، سود (ربا) اور رشوت سے اجتناب، تحریری معاہدات، امانتوں کی ادائیگی اور میانہ روی۔"}, {"id": "family", "title_ur": "والدین، خاندان اور عفت و پاکدامنی", "title_en": "Family, Parents & Gender Modesty", "icon": "👨‍👩‍👧", "color": "#ec4899", "description_ur": "والدین کی تعظیم، اف نہ کہنا، ازواجی حسنِ سلوک، نگاہوں کی حفاظت اور زنا و بدکاری سے ممانعت۔"}, {"id": "justice", "title_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "title_en": "Justice, Human Rights & Humility", "icon": "🏛️", "color": "#6366f1", "description_ur": "بلا امتیاز عدل، دشمن سے بھی انصاف، انسانی جان کا تحفظ، زمین پر عاجزی سے چلنا اور ظلم کی نفی۔"}], "items": [{"serial": 1, "id": "cmd_001", "surah_id": 2, "ayah_num": 168, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "command", "title_ur": "زمین کی حلال اور پاکیزہ چیزیں کھاؤ", "title_en": "Eat Wholesome & Lawful Sustenance", "arabic": "یٰۤاَیُّهَا النَّاسُ كُلُوْا مِمَّا فِی الْاَرْضِ حَلٰلًا طَیِّبًا ۖ وَّلَا تَتَّبِعُوْا خُطُوٰتِ الشَّیْطٰنِؕ-اِنَّهٗ لَكُمْ عَدُوٌّ مُّبِیْنٌ", "translation_urdu_kanzul_iman": "اے لوگوں کھاؤ جو کچھ زمین میں حلال پاکیزہ ہے اور شیطان کے قدم پر قدم نہ رکھو، بیشک وہ تمہارا کھلا دشمن ہے۔", "translation_urdu_kanzul_irfan": "اے لوگو! جو کچھ زمین میں  حلال پاکیزہ ہے اس میں  سے کھاؤ اور شیطان کے راستوں  پر نہ چلو، بیشک وہ تمہارا کھلا دشمن ہے۔", "translation_english": "O people! Eat what is lawful and pure on the earth, and do not follow the footsteps of the Devil; undoubtedly, he is your open enemy.", "wisdom_benefit_ur": "پاکیزہ اور حلال خوراک جسم کو مہلک زہروں، انفیکشن اور غیر صحت بخش اجزاء سے بچاتی ہے اور باطنی پاکیزگی و توانائی پیدا کرتی ہے۔", "wisdom_benefit_en": "Consuming pure, wholesome (Tayyib) nutrition protects the body from harmful toxins, microbial contamination, and promotes cellular health and metabolic vitality."}, {"serial": 2, "id": "cmd_002", "surah_id": 5, "ayah_num": 90, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "prohibition", "title_ur": "شراب اور جوئے سے قطعی بچو", "title_en": "Strictly Avoid Alcohol & Gambling", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اِنَّمَا الْخَمْرُ وَالْمَیْسِرُ وَالْاَنْصَابُ وَالْاَزْلَامُ رِجْسٌ مِّنْ عَمَلِ الشَّیْطٰنِ فَاجْتَنِبُوْهُ لَعَلَّكُمْ تُفْلِحُوْنَ", "translation_urdu_kanzul_iman": "اے ایمان والوشراب اور جُوا اور بت اور پانسے ناپاک ہی ہیں شیطانی کام تو ان سے بچتے رہنا کہ تم فلاح پاؤ۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! شراب اور جوا اور بت اور قسمت معلوم کرنے کے تیر ناپاک شیطانی کام ہی ہیں  تو ان سے بچتے رہو تاکہ تم فلاح پاؤ۔", "translation_english": "O believers! Wine, and gambling, and idols, and fortune-telling arrows (to ascertain luck or predict future events) are but impure; the works of the Devil. Therefore, keep avoiding them in order that you may attain success.", "wisdom_benefit_ur": "شراب جگر، اعصابی نظام اور دماغی فیصلہ سازی کو تباہ کرتی ہے، جبکہ جوا ذہنی تناؤ، ڈیپریشن اور معاشی بربادی کا سبب بنتا ہے۔", "wisdom_benefit_en": "Alcohol causes progressive neurotoxic damage, liver cirrhosis, and addiction, while gambling triggers acute neuro-chemical stress, depression, and financial collapse."}, {"serial": 3, "id": "cmd_003", "surah_id": 2, "ayah_num": 173, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "prohibition", "title_ur": "مردار، بہتا خون اور سور کا گوشت نہ کھاؤ", "title_en": "Do Not Consume Carrion, Blood, or Pork", "arabic": "اِنَّمَا حَرَّمَ عَلَیْكُمُ الْمَیْتَةَ وَالدَّمَ وَلَحْمَ الْخِنْزِیْرِ وَمَاۤ اُهِلَّ بِهٖ لِغَیْرِ اللّٰهِۚ-فَمَنِ اضْطُرَّ غَیْرَ بَاغٍ وَّلَا عَادٍ فَلَاۤ اِثْمَ عَلَیْهِؕ-اِنَّ اللّٰهَ غَفُوْرٌ رَّحِیْمٌ", "translation_urdu_kanzul_iman": "اس نے یہی تم پر حرام کئے ہیں مردار اور خون اور سُور کا گوشت اور وہ جانور جو غیر خدا کا نام لے کر ذبح کیا گیا تو جو نا چار ہو نہ یوں کہ خواہش سے کھائے اور نہ یوں کہ ضرورت سے آگے بڑھے تو اس پر گناہ نہیں بیشک  اللہ  بخشنے والا مہربان ہے۔", "translation_urdu_kanzul_irfan": "اس نے تم پر صرف مردار اور خون اور سُور کا گوشت اور وہ جانور حرام کئے ہیں  جس کے ذبح کے وقت غیرُ اللہ کا نام بلند کیا گیا تو جو مجبور ہوجائے حالانکہ وہ نہ خواہش رکھنے والا ہو اور نہ ضرورت سے آگے بڑھنے والاہو تو اس پر کوئی گناہ نہیں  ،بیشک اللہ  بخشنے والا مہربان ہے۔", "translation_english": "He (Allah) has forbidden (the eating of) only these for you; a dead animal (i.e. carrion), and blood, and the flesh of swine, and the animal upon which the name of other than Allah is proclaimed at the time of slaughtering. So (for consuming the above), there is no sin upon the one who is compelled and does not eat out of desire, nor transgressing the limit (of eating). Indeed, Allah is Most Forgiving, Most Merciful.", "wisdom_benefit_ur": "مردار اور خون جراثیم و بیکٹیریا کا گڑھ ہوتے ہیں اور سور کا گوشت طفیلی کیڑوں (پیراسائٹس) اور شدید کولیسٹرول کا باعث بنتا ہے۔", "wisdom_benefit_en": "Carrion and unpurified blood harbor dangerous microbial pathogens, while pork tissue carries high parasitic burdens (trichinella) and atherogenic saturated lipids."}, {"serial": 4, "id": "cmd_004", "surah_id": 7, "ayah_num": 31, "surah_name_en": "Al Araf", "surah_name_ar": "اَلْاَعْرَاف", "surah_name_roman": "Al Araf", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "command", "title_ur": "خوب کھاؤ اور پیو مگر اسراف (حد سے تجاوز) نہ کرو", "title_en": "Eat and Drink in Moderation — Do Not Waste", "arabic": "یٰبَنِیْۤ اٰدَمَ خُذُوْا زِیْنَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ وَّكُلُوْا وَاشْرَبُوْا وَلَا تُسْرِفُوْا ۚ-اِنَّهٗ لَا یُحِبُّ الْمُسْرِفِیْنَ۠", "translation_urdu_kanzul_iman": "اے آدم کی اولاد اپنی زینت لو جب مسجد میں جاؤ اور کھاؤ اور پیو اور حد سے نہ بڑھو بیشک حد سے بڑھنے والے اسے پسند نہیں۔", "translation_urdu_kanzul_irfan": "اے آدم کی اولاد! ہر نمازکے وقت اپنی زینت لے لو اور کھاؤ اور پیو اور حد سے نہ بڑھو بیشک وہ حد سے بڑھنے والوں  کو پسند نہیں  فرماتا۔", "translation_english": "O children of Adam! Adorn yourself when you go to the Masjid, and eat and drink, and do not cross the limit; indeed, He does not like those who cross the limit (i.e. the extravagant).", "wisdom_benefit_ur": "زیادہ خوری موٹاپا، ذیابیطس، ہائی بلڈ پریشر اور معدے کے امراض کی جڑ ہے۔ اعتدال پسندانہ خوراک لمبی عمر اور چستی کی ضامن ہے۔", "wisdom_benefit_en": "Overeating and dietary excess directly trigger obesity, metabolic syndrome, type 2 diabetes, and cardiovascular strain. Caloric moderation preserves cellular longevity."}, {"serial": 5, "id": "cmd_005", "surah_id": 2, "ayah_num": 195, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "prohibition", "title_ur": "اپنے آپ کو اپنے ہاتھوں ہلاکت میں نہ ڈالو", "title_en": "Do Not Cast Yourselves into Destruction", "arabic": "وَاَنْفِقُوْا فِیْ سَبِیْلِ اللّٰهِ وَلَا تُلْقُوْا بِاَیْدِیْكُمْ اِلَى التَّهْلُكَةِ ۛ- وَاَحْسِنُوْاۚۛ-اِنَّ اللّٰهَ یُحِبُّ الْمُحْسِنِیْنَ", "translation_urdu_kanzul_iman": "اور  اللہ  کی راہ میں خرچ کرو اور اپنے ہاتھوں ہلاکت میں نہ پڑو اور بھلائی والے ہو جاؤ بیشک بھلائی والے  اللہ  کے محبوب ہیں۔", "translation_urdu_kanzul_irfan": "اور اللہ  کی راہ میں  خرچ کرو اور اپنے ہاتھوں  خودکو ہلاکت میں  نہ ڈالو اورنیکی کرو بیشک اللہ  نیکی کرنے والوں  سے محبت فرماتاہے۔", "translation_english": "And spend in the path of Allah, and do not fall into destruction by your own hands, and become virtuous; undoubtedly, the virtuous are the beloveds of Allah.", "wisdom_benefit_ur": "تمباکو نوشی، نشہ، غیر محفوظ ڈرائیونگ اور صحت کو برباد کرنے والی خطرناک عادات سے بچنا شرعی اور انسانی فرض ہے۔", "wisdom_benefit_en": "Establishes a fundamental health directive prohibiting substance abuse, self-harm, reckless physical behaviors, and habits detrimental to physiological survival."}, {"serial": 6, "id": "cmd_006", "surah_id": 4, "ayah_num": 29, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "prohibition", "title_ur": "اپنی جانوں کو مت مارو (خودکشی و قتلِ نفس کی ممانعت)", "title_en": "Do Not Kill Yourselves (Prohibition of Suicide)", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تَاْكُلُوْۤا اَمْوَالَكُمْ بَیْنَكُمْ بِالْبَاطِلِ اِلَّاۤ اَنْ تَكُوْنَ تِجَارَةً عَنْ تَرَاضٍ مِّنْكُمْ ؕ وَلَا تَقْتُلُوْۤا اَنْفُسَكُمْؕ-اِنَّ اللّٰهَ كَانَ بِكُمْ رَحِیْمًا", "translation_urdu_kanzul_iman": "اے ایمان والو آپس میں ایک دوسرے کے مال ناحق نہ کھاؤ مگر یہ کہ کوئی سودا تمہاری باہمی رضا مندی کا ہو اور اپنی جانیں قتل نہ کرو بیشک  اللہ  تم پر مہربان ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! باطل طریقے سے آپس میں  ایک دوسرے کے مال نہ کھاؤ البتہ یہ (ہو) کہ تمہاری باہمی رضامندی سے تجارت ہو اور اپنی جانوں  کو قتل نہ کرو۔ بیشک اللہ  تم پر مہربان ہے۔", "translation_english": "O believers! Do not unfairly consume the wealth of each other, except that it is a trade by your mutual agreement, and do not kill yourselves (by committing murder, or suicide, etc.). Indeed, Allah is Most Merciful upon you.", "wisdom_benefit_ur": "انسانی جان اللہ کی مقدس امانت ہے۔ یہ حکم ذہنی و نفسیاتی تحفظ اور مشکلات میں ثابت قدم رہنے کا عظیم درس دیتا ہے۔", "wisdom_benefit_en": "Sanctifies biological and psychological life, explicitly outlawing self-termination and reinforcing spiritual resilience against psychological despair."}, {"serial": 7, "id": "cmd_007", "surah_id": 5, "ayah_num": 6, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "command", "title_ur": "نماز کے لیے چہرہ، ہاتھ اور پاؤں دھو کر باوضو رہو", "title_en": "Maintain Daily Physical Purification via Wudu", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اِذَا قُمْتُمْ اِلَى الصَّلٰوةِ فَاغْسِلُوْا وُجُوْهَكُمْ وَاَیْدِیَكُمْ اِلَى الْمَرَافِقِ وَامْسَحُوْا بِرُءُوْسِكُمْ وَاَرْجُلَكُمْ اِلَى الْكَعْبَیْنِؕ-وَاِنْ كُنْتُمْ جُنُبًا فَاطَّهَّرُوْاؕ-وَاِنْ كُنْتُمْ مَّرْضٰۤى اَوْ عَلٰى سَفَرٍ اَوْ جَآءَ اَحَدٌ مِّنْكُمْ مِّنَ الْغَآىٕطِ اَوْ لٰمَسْتُمُ النِّسَآءَ فَلَمْ تَجِدُوْا مَآءً فَتَیَمَّمُوْا صَعِیْدًا طَیِّبًا فَامْسَحُوْا بِوُجُوْهِكُمْ وَاَیْدِیْكُمْ مِّنْهُؕ-مَا یُرِیْدُ اللّٰهُ لِیَجْعَلَ عَلَیْكُمْ مِّنْ حَرَجٍ وَّلٰـكِنْ یُّرِیْدُ لِیُطَهِّرَكُمْ وَلِیُتِمَّ نِعْمَتَهٗ عَلَیْكُمْ لَعَلَّكُمْ تَشْكُرُوْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو جب نماز کو کھڑے ہونا چاہو تو اپنے منہ دھوؤ اور کہنیوں تک ہاتھ اور سروں کا مسح کرو اور گٹوں تک پاؤ ں دھوؤ اور اگر تمہیں نہانے کی حاجت ہو تو خوب ستھرے ہولو اور اگر تم بیمار یا سفر میں ہو یا تم میں کوئی قضائے حاجت سے آیا یا تم نے عورتوں سے صحبت کی اور ان صورتوں میں پانی نہ پایا تو پاک مٹی سے تیمم کرو تو اپنے منہ اور ہاتھوں کا اس سے مسح کرو،  اللہ  نہیں چاہتا کہ تم پر کچھ تنگی رکھے ہاں یہ چاہتا ہے کہ تمہیں خوب ستھرا کردے اور اپنی نعمت تم پر پوری کردے کہ کہیں تم احسان مانو۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! جب تم نماز کی طرف کھڑے ہونے لگو تو اپنے چہروں  کو اور اپنے ہاتھ کہنیوں  تک دھو لو اور سروں  کا مسح کرو اور ٹخنوں  تک پاؤ ں  دھولو اور اگر تم بے غسل ہو تو خوب پاک ہوجاؤ اور اگر تم بیمار ہو یا سفر میں  ہو یا تم میں  سے کوئی بیتُ الخلاء سے آیا ہویا تم نے عورتوں  سے صحبت کی ہواور ان صورتوں  میں  پانی نہ پاؤ توپاک مٹی سے تیمم کرلو تو اپنے چہروں  اور ہاتھوں  کا اس سے مسح کرلو۔ اللہ  نہیں  چاہتا کہ تم پر کچھ تنگی رکھے لیکن وہ یہ چاہتا ہے کہ تمہیں  خوب پاک کردے اور اپنی نعمت تم پر پوری کردے تاکہ تم شکر ادا کرو۔", "translation_english": "O believers! When you intend to stand up for Salah; so, wash your faces, and your hands up to (i.e. including) the elbows, and pass wet hands (i.e. perform Massah - wipe) over your heads and wash your feet up to (i.e. including) the ankles. And if you need to have an obligatory bath; so, clean yourselves thoroughly, and if you are sick or on a journey, or if any of you comes having responded to the call of nature, or you have had intercourse with your wives; and in these conditions you do not find water, so, perform Tayammum with pure sand; hence, rub your faces therewith and your hands (i.e. including the forearms as well as the elbows). Allah does not will to place any hardship upon you. Yes; He wills to purify you totally and complete His Favour upon you (so) that you may be grateful.", "wisdom_benefit_ur": "دن میں پانچ بار منہ، ہاتھ، ناک اور پاؤں دھونا وبائی امراض، جلد کے انفیکشن اور بیکٹیریا کے پھیلاؤ کو جڑ سے ختم کرتا ہے۔", "wisdom_benefit_en": "Repeated daily ablution (Wudu) provides clinical-grade micro-hygiene for exposed mucous membranes and extremities, preventing pathogenic bacterial transmission."}, {"serial": 8, "id": "cmd_008", "surah_id": 74, "ayah_num": 4, "surah_name_en": "Al Mudassir", "surah_name_ar": "اَلْمُدَّثِّر", "surah_name_roman": "Al Mudassir", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "command", "title_ur": "اپنے کپڑے خوب پاکیزہ رکھو", "title_en": "Keep Your Garments Clean and Pure", "arabic": "وَثِیَابَكَ فَطَهِّرْۙ", "translation_urdu_kanzul_iman": "اور اپنے کپڑے پاک رکھو۔", "translation_urdu_kanzul_irfan": "اور اپنے کپڑے پاک رکھو۔", "translation_english": "And keep your clothes pure.", "wisdom_benefit_ur": "صاف ستھرا لباس جلدی بیماریوں سے بچاتا ہے اور انسان میں خود اعتمادی، وقار اور فرحت بخش احساس پیدا کرتا ہے۔", "wisdom_benefit_en": "Clean clothing prevents dermal fungal infections and fosters psychological uplift, social dignity, and environmental hygiene."}, {"serial": 9, "id": "cmd_009", "surah_id": 78, "ayah_num": 9, "surah_name_en": "An Naba", "surah_name_ar": "اَلنَّبَا", "surah_name_roman": "An Naba", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "command", "title_ur": "رات کو سکون و نیند کے لیے اور دن کو روزی کے لیے بناؤ", "title_en": "Respect Natural Sleep & Circadian Biology", "arabic": "وَّجَعَلْنَا نَوْمَكُمْ سُبَاتًاۙ", "translation_urdu_kanzul_iman": "اور تمہاری نیند کو آرام کیا۔", "translation_urdu_kanzul_irfan": "اور تمہاری نیند کو آرام کا ذریعہ بنایا۔", "translation_english": "And (We) made your sleep a (means of) rest.", "wisdom_benefit_ur": "فطری حیاتیاتی گھڑی (سرکیڈین ردھم) کے مطابق رات کو سونا خلیات کی مرمت، ہارمونز کے توازن اور ذہنی تروتازگی کے لیے ناگزیر ہے۔", "wisdom_benefit_en": "Aligns human behavior with the endogenous circadian rhythm; nighttime sleep facilitates cellular neuro-restoration and metabolic detoxification."}, {"serial": 10, "id": "cmd_010", "surah_id": 2, "ayah_num": 222, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "health", "category_name_ur": "صحت، غذا اور طہارت", "category_name_en": "Health, Nutrition & Cleanliness", "category_icon": "🥗", "category_color": "#10b981", "polarity": "command", "title_ur": "اللہ توبہ کرنے والوں اور خوب پاک صاف رہنے والوں کو محبوب رکھتا ہے", "title_en": "Love and Practice Continuous Purity", "arabic": "وَیَسْــٴَـلُوْنَكَ عَنِ الْمَحِیْضِؕ-قُلْ هُوَ اَذًىۙ-فَاعْتَزِلُوا النِّسَآءَ فِی الْمَحِیْضِۙ-وَلَا تَقْرَبُوْهُنَّ حَتّٰى یَطْهُرْنَۚ-فَاِذَا تَطَهَّرْنَ فَاْتُوْهُنَّ مِنْ حَیْثُ اَمَرَكُمُ اللّٰهُؕ-اِنَّ اللّٰهَ یُحِبُّ التَّوَّابِیْنَ وَیُحِبُّ الْمُتَطَهِّرِیْنَ", "translation_urdu_kanzul_iman": "اور تم سے پوچھتے ہیں حیض کا حکم تم فرماؤ وہ ناپاکی ہے تو عورتوں سے الگ رہو حیض کے دنوں اور ان سے نزدیکی نہ کرو جب تک پاک نہ ہولیں پھر جب پاک ہوجائیں تو ان کے پاس جاؤ جہاں سے تمہیں  اللہ  نے حکم دیا بیشک  اللہ  پسند رکھتا ہے بہت توبہ کرنے والوں کو اور پسند رکھتا ہے ستھروں کو۔", "translation_urdu_kanzul_irfan": "اور تم سے حیض کے بارے میں  پوچھتے ہیں  تم فرماؤ: وہ ناپاکی ہے تو حیض کے دنوں  میں  عورتوں  سے الگ رہو اور ان کے قریب نہ جاؤ جب تک پاک نہ ہوجائیں پھر جب خوب پاک ہوجائیں   تو ان کے پاس وہاں  سے جاؤ جہاں  سے تمہیں  اللہ  نے حکم دیاہے ، بیشک اللہ  بہت توبہ کرنے والوں  سے محبت فرماتا ہے اور خوب صاف ستھرے رہنے والوں  کو پسند فرماتا ہے۔", "translation_english": "And they ask you (O Beloved) the ruling regarding menstruation. Say you, 'It is impurity, so stay away from women in the days of menstruation, and do not approach them until they are pure. Then, when they become pure, so approach them from where Allah has commanded you.' Indeed, Allah loves those who repent abundantly and loves those who purify themselves.", "wisdom_benefit_ur": "ظاہری و باطنی صفائی انسانی شخصیت کو نکھارتی ہے اور ذہنی الجھنوں و جسمانی آلائشوں سے محفوظ رکھتی ہے۔", "wisdom_benefit_en": "Integrates moral cleanliness with physiological asepsis, creating emotional peace and an elevated state of physical hygiene."}, {"serial": 11, "id": "cmd_011", "surah_id": 31, "ayah_num": 19, "surah_name_en": "Luqman", "surah_name_ar": "لُقْمٰن", "surah_name_roman": "Luqman", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "command", "title_ur": "اپنی آواز نیچی رکھو، بے ہودہ چیخ و پکار نہ کرو", "title_en": "Lower Your Voice; Speak Softly and Calmly", "arabic": "وَاقْصِدْ فِیْ مَشْیِكَ وَاغْضُضْ مِنْ صَوْتِكَؕ-اِنَّ اَنْكَرَ الْاَصْوَاتِ لَصَوْتُ الْحَمِیْرِ۠", "translation_urdu_kanzul_iman": "اور میانہ چال چل اور اپنی آواز کچھ پست کر بیشک سب آوازوں  میں  بری آواز، گدھے کی آواز۔", "translation_urdu_kanzul_irfan": "اور اپنے چلنے میں   درمیانی چال سے چل اور اپنی آواز کچھ پست رکھ، بیشک سب سے بری آواز گدھے کی آواز ہے۔", "translation_english": "'And walk moderately and lower your voice to some extent; indeed, the worst voice amongst the voices is the braying of a donkey.'", "wisdom_benefit_ur": "چیخنے سے گریز بلڈ پریشر اور غصے کو قابو میں رکھتا ہے اور پرسکون، پر اثر اور پر وقار مکالمے کو جنم دیتا ہے۔", "wisdom_benefit_en": "Lowering vocal volume prevents autonomic nervous arousal, de-escalates interpersonal friction, and enhances conversational influence."}, {"serial": 12, "id": "cmd_012", "surah_id": 17, "ayah_num": 53, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "command", "title_ur": "وہ بات کہو جو سب سے عمدہ اور شائستہ ہو", "title_en": "Speak That Which Is Best and Most Courteous", "arabic": "وَقُلْ لِّعِبَادِیْ یَقُوْلُوا الَّتِیْ هِیَ اَحْسَنُؕ-اِنَّ الشَّیْطٰنَ یَنْزَغُ بَیْنَهُمْؕ-اِنَّ الشَّیْطٰنَ كَانَ لِلْاِنْسَانِ عَدُوًّا مُّبِیْنًا", "translation_urdu_kanzul_iman": "اور میرے بندوں  سے فرماؤ وہ بات کہیں  جو سب سے اچھی ہو بیشک شیطان ان کے آپس میں  فساد ڈال دیتا ہے بیشک شیطان آدمی کا کھلا دشمن ہے۔", "translation_urdu_kanzul_irfan": "اور اے حبیب! آپ میرے بندوں   سے فرما دیں   کہ وہ ایسی بات کہیں   جو سب سے اچھی ہو۔ بیشک شیطان لوگوں   کے درمیان فساد ڈال دیتا ہے ۔ بیشک شیطان انسان کا کھلا دشمن ہے۔", "translation_english": "And tell My bondsmen to speak that which is best. Undoubtedly, the Devil causes mischief amongst them; indeed, the Devil is an open enemy of mankind.", "wisdom_benefit_ur": "شائستہ الفاظ شیطان کی ڈالی ہوئی غلط فہمیوں اور رشتوں کے بگاڑ کا بہترین سدِ باب ہیں۔", "wisdom_benefit_en": "Selecting courteous speech prevents toxic cognitive misinterpretations, diffuses adversarial tension, and fortifies relational empathy."}, {"serial": 13, "id": "cmd_013", "surah_id": 2, "ayah_num": 83, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "command", "title_ur": "تمام لوگوں سے بھلی اور خوش اخلاقی کی بات کہو", "title_en": "Speak Kindly to All People Without Prejudice", "arabic": "وَاِذْ اَخَذْنَا مِیْثَاقَ بَنِیْۤ اِسْرَآءِیْلَ لَا تَعْبُدُوْنَ اِلَّا اللّٰهَ ؕ وَبِالْوَالِدَیْنِ اِحْسَانًا وَّذِی الْقُرْبٰى وَالْیَتٰمٰى وَالْمَسٰكِیْنِ وَقُوْلُوْا لِلنَّاسِ حُسْنًا وَّاَقِیْمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَؕ-ثُمَّ تَوَلَّیْتُمْ اِلَّا قَلِیْلًا مِّنْكُمْ وَاَنْتُمْ مُّعْرِضُوْنَ", "translation_urdu_kanzul_iman": "اور جب ہم نے بنی اسرائیل سے عہد لیا کہ  اللہ  کے سوا کسی کو نہ پوجو اور ماں باپ کے ساتھ بھلائی کرو  اور رشتہ داروں اور یتیموں اور مسکینوں سے اور لوگوں سے اچھی بات کہو  اور نماز قائم رکھو اور زکوٰۃ دو پھر تم پھِر گئے  مگر تم میں کے تھوڑے  اور تم رو گرداں ہو ۔", "translation_urdu_kanzul_irfan": "اور یاد کروجب ہم نے بنی اسرائیل سے عہدلیا کہ اللہ  کے سوا کسی کی عبادت نہ کرو اور ماں  باپ کے ساتھ بھلائی کرو اور رشتہ داروں  اور یتیموں  اور مسکینوں  کے ساتھ (اچھا سلوک کرو) اور لوگوں  سے اچھی بات کہو اور نماز قائم رکھو اور زکوٰۃ دو (لیکن)پھر تم میں  سے چند آدمیوں  کے علاوہ سب پھر گئے اور تم (ویسے ہی اللہ  کے احکام سے)منہ موڑنے والے ہو۔", "translation_english": "And when We took a covenant from the Children of Israel; that do not worship anyone other than Allah, and be good to parents, and relatives, and orphans and the needy, and speak good to people, and keep Salah established and pay Zakah. You then turned away (from that covenant) except a few amongst you, and you are (merely) the ones who turn their faces away (from the commands of Allah).", "wisdom_benefit_ur": "ہر مذہب، رنگ اور نسل کے انسان سے مسکرا کر اچھی بات کہنا دلوں کو جوڑتا ہے اور معاشرتی امن پیدا کرتا ہے۔", "wisdom_benefit_en": "Universal verbal kindness dissolves social hostility, fosters cross-cultural harmony, and validates the shared dignity of all human beings."}, {"serial": 14, "id": "cmd_014", "surah_id": 20, "ayah_num": 44, "surah_name_en": "Taha", "surah_name_ar": "طٰهٰ", "surah_name_roman": "Taha", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "command", "title_ur": "مخالف اور سرکش سے بھی نرم لہجے میں بات کرو", "title_en": "Speak Gently Even to Hardened Opponents", "arabic": "فَقُوْلَا لَهٗ قَوْلًا لَّیِّنًا لَّعَلَّهٗ یَتَذَكَّرُ اَوْ یَخْشٰى", "translation_urdu_kanzul_iman": "تو اس سے نرم بات کہنا اس امید پر کہ وہ دھیان کرے یا کچھ ڈرے۔", "translation_urdu_kanzul_irfan": "توتم اس سے نرم بات کہنا اس امید پر کہ شاید وہ نصیحت قبول کرلے یا ڈرجائے۔", "translation_english": "'So, speak to him gently in the hope that he may reflect or have some fear.'", "wisdom_benefit_ur": "نرمی سب سے بڑے مخالف کے دل میں بھی غور و فکر اور توبہ کی کھڑکی کھول دیتی ہے، جبکہ تلخی ضد پیدا کرتی ہے۔", "wisdom_benefit_en": "Gentle communication bypasses emotional defense mechanisms in adversarial dialogues, opening the door for genuine rational reflection."}, {"serial": 15, "id": "cmd_015", "surah_id": 33, "ayah_num": 70, "surah_name_en": "Al Ahzab", "surah_name_ar": "اَلْاَحْزَاب", "surah_name_roman": "Al Ahzab", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "command", "title_ur": "اللہ سے ڈرو اور بالکل سیدھی سچی بات کہو", "title_en": "Speak Straightforward and Unmanipulated Truth", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَقُوْلُوْا قَوْلًا سَدِیْدًاۙ", "translation_urdu_kanzul_iman": "اے ایمان والو  اللہ  سے ڈرو اور سیدھی بات کہو۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! اللہ  سے ڈرو اور سیدھی بات کہاکرو۔", "translation_english": "O believers! Fear Allah, and talk straight.", "wisdom_benefit_ur": "سچائی سے معاملات سلجھتے ہیں، گناہ معاف ہوتے ہیں اور معاشرے میں اعتماد و شفافیت کی فضا قائم ہوتی ہے۔", "wisdom_benefit_en": "Transparent, unmanipulated honesty eliminates the cognitive burden of deception, builds high-trust institutions, and rectifies communal affairs."}, {"serial": 16, "id": "cmd_016", "surah_id": 23, "ayah_num": 3, "surah_name_en": "Al Muminun", "surah_name_ar": "اَلْمُؤْمِنُوْن", "surah_name_roman": "Al Muminun", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "prohibition", "title_ur": "فضول، لایعنی اور بیہودہ باتوں سے منہ پھیر لو", "title_en": "Shun Vain, Worthless, and Idle Talk", "arabic": "وَالَّذِیْنَ هُمْ عَنِ اللَّغْوِ مُعْرِضُوْنَۙ", "translation_urdu_kanzul_iman": "اور وہ جو کسی بیہودہ بات کی طرف اِلتفات نہیں  کرتے۔", "translation_urdu_kanzul_irfan": "اور وہ جو فضول بات سے منہ پھیرنے والے ہیں۔", "translation_english": "And who do not incline towards vain talk.", "wisdom_benefit_ur": "لایعنی گفتگو وقت کا زیاں اور ذہنی توانائی کا زوال ہے۔ خاموشی یا بامقصد گفتگو ذہن کو تیز اور نتیجہ خیز رکھتی ہے۔", "wisdom_benefit_en": "Eliminating gossip and trivial speech conserves cognitive focus, enhances mental productivity, and prevents informational toxicity."}, {"serial": 17, "id": "cmd_017", "surah_id": 6, "ayah_num": 108, "surah_name_en": "Al Anam", "surah_name_ar": "اَلْاَ نْعَام", "surah_name_roman": "Al Anam", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "prohibition", "title_ur": "دوسروں کے معبودوں کو برا نہ کہو", "title_en": "Do Not Revile What Others Worship", "arabic": "وَلَا تَسُبُّوا الَّذِیْنَ یَدْعُوْنَ مِنْ دُوْنِ اللّٰهِ فَیَسُبُّوا اللّٰهَ عَدْوًۢا بِغَیْرِ عِلْمٍؕ-كَذٰلِكَ زَیَّنَّا لِكُلِّ اُمَّةٍ عَمَلَهُمْ۪-ثُمَّ اِلٰى رَبِّهِمْ مَّرْجِعُهُمْ فَیُنَبِّئُهُمْ بِمَا كَانُوْا یَعْمَلُوْنَ", "translation_urdu_kanzul_iman": "اور انہیں گالی نہ دو جن کو وہ  اللہ  کے سوا پوجتے ہیں کہ وہ  اللہ  کی شان میں بے ادبی کریں گے زیادتی اور جہالت سے یونہی ہم نے ہر اُمت کی نگاہ میں اس کے عمل بھلے کردیے ہیں پھر انہیں اپنے رب کی طرف پھرنا ہے اور وہ انہیں بتادے گا جو کرتے تھے۔", "translation_urdu_kanzul_irfan": "اور اُنہیں  برابھلا نہ کہو جنہیں  وہ اللہ  کے سوا پوجتے ہیں  کہ وہ زیادتی کرتے ہوئے جہالت کی وجہ سے اللہ  کی شان میں  بے ادبی کریں  گے یونہی ہم نے ہر اُمت کی نگاہ میں  اس کے عمل کو آراستہ کردیا پھر انہیں  اپنے رب کی طرف پھرنا ہے تو وہ انہیں  بتادے گا جووہ کرتے تھے۔", "translation_english": "Do not use offensive words against those (false deities) whom they worship other than Allah; that they (in retaliation) will insult Allah's Glory through injustice and ignorance. Likewise, in the eyes of every nation, We have made their deeds appear good, they are then to return towards their Lord, and He will inform them of what they used to do.", "wisdom_benefit_ur": "دوسروں کے عقائد کی توہین انتقامی نفرت اور فتنہ و فساد کا باعث بنتی ہے۔ باہمی احترام ہی پرامن بقائے باہمی کا راز ہے۔", "wisdom_benefit_en": "Forbids sectarian insults and cultural vilification, neutralizing retaliatory fanaticism and establishing mutual civic peace."}, {"serial": 18, "id": "cmd_018", "surah_id": 25, "ayah_num": 72, "surah_name_en": "Al Furqan", "surah_name_ar": "اَلْفُرْقَان", "surah_name_roman": "Al Furqan", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "prohibition", "title_ur": "جھوٹی گواہی نہ دو اور لغو کے پاس سے باوقار گزرو", "title_en": "Do Not Bear False Witness; Pass Vulgarity with Dignity", "arabic": "وَالَّذِیْنَ لَا یَشْهَدُوْنَ الزُّوْرَۙ-وَاِذَا مَرُّوْا بِاللَّغْوِ مَرُّوْا كِرَامًا", "translation_urdu_kanzul_iman": "اور جو جھوٹی گواہی نہیں  دیتے اور جب بیہودہ پر گزرتے ہیں  اپنی عزت سنبھالے گزر جاتے ہیں ۔", "translation_urdu_kanzul_irfan": "اور جو جھوٹی گواہی نہیں  دیتے اور جب کسی بیہودہ بات کے پاس سے گزرتے ہیں  تواپنی عزت سنبھالتے ہوئے گزر جاتے ہیں ۔", "translation_english": "And those who do not give false testimony, and when they pass by (something) immoral, they pass by protecting their honour.", "wisdom_benefit_ur": "جھوٹی گواہی بے گناہ کو تباہ کرتی ہے اور عدلیہ کا وقار خاک میں ملا دیتی ہے۔ حق پر قائم رہنا عدل کی بنیاد ہے۔", "wisdom_benefit_en": "Perjury subverts the legal fabric of society; refusing false testimony protects the innocent and upholds institutional integrity."}, {"serial": 19, "id": "cmd_019", "surah_id": 4, "ayah_num": 148, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "prohibition", "title_ur": "برائی اور بدزبانی کو سرِ عام پھیلانا پسند نہیں کیا جاتا", "title_en": "Do Not Publicize Evil Speech or Slander", "arabic": "لَا یُحِبُّ اللّٰهُ الْجَهْرَ بِالسُّوْٓءِ مِنَ الْقَوْلِ اِلَّا مَنْ ظُلِمَؕ-وَكَانَ اللّٰهُ سَمِیْعًا عَلِیْمًا", "translation_urdu_kanzul_iman": "اللہ  پسند نہیں کرتا بری بات کا اعلان کرنا مگر مظلوم سے اور  اللہ   سنتا جانتا ہے۔", "translation_urdu_kanzul_irfan": "بری بات کا اعلان کرنا اللہ  پسند نہیں  کرتا مگر مظلوم سے اور اللہ  سننے والا جاننے والا ہے۔", "translation_english": "Allah does not like the public utterance of evil talk except by the oppressed, and Allah is All-Hearing, All-Knowing.", "wisdom_benefit_ur": "برائی اور فحش کلامی کو سوشل میڈیا یا گلی کوچوں میں اچھالنا معاشرے کی اجتماعی حیا کو ختم کرتا ہے۔", "wisdom_benefit_en": "Restraining public dissemination of vulgarity and scandals protects societal decency and minimizes sensationalized cultural decay."}, {"serial": 20, "id": "cmd_020", "surah_id": 28, "ayah_num": 55, "surah_name_en": "Al Qasas", "surah_name_ar": "اَلْقَصَص", "surah_name_roman": "Al Qasas", "category_id": "speech", "category_name_ur": "گفتگو، لہجہ اور آدابِ کلام", "category_name_en": "Speech, Tone & Gentle Conversation", "category_icon": "🗣️", "category_color": "#38bdf8", "polarity": "command", "title_ur": "بیہودہ بات سن کر الجھنے کے بجائے 'سلام' کہہ کر گزر جاؤ", "title_en": "Respond to Hostility with Peaceful Exit", "arabic": "وَاِذَا سَمِعُوا اللَّغْوَ اَعْرَضُوْا عَنْهُ وَقَالُوْا لَنَاۤ اَعْمَالُنَا وَلَكُمْ اَعْمَالُكُمْ٘-سَلٰمٌ عَلَیْكُمْ٘-لَا نَبْتَغِی الْجٰهِلِیْنَ", "translation_urdu_kanzul_iman": "اور جب بیہودہ بات سنتے ہیں  اس سے تغافل کرتے ہیں  اور کہتے ہیں  ہمارے لیے ہمارے عمل اور تمہارے لیے تمہارے عمل بس تم پر سلام ہم جاہلوں  کے غرضی  نہیں ۔", "translation_urdu_kanzul_irfan": "اور جب بیہودہ بات سنتے ہیں   اس سے منہ پھیر لیتے ہیں   اور کہتے ہیں  : ہمارے لیے ہمارے اعمال ہیں   اور تمہارے لیے تمہارے اعمال ہیں  ۔ بس تمہیں  سلام، ہم جاہلوں   کا ساتھ نہیں   چاہتے۔", "translation_english": "And when they hear obscene talk, they turn away and say, 'For us are our deeds and for you are your deeds. Enough! Peace be upon you (i.e. an expression of disapproval); we are not interested in the ignorant.'", "wisdom_benefit_ur": "جاہلوں اور بدزبانوں سے بحث میں الجھنے کے بجائے باوقار واپسی ذہنی سکون اور وقت دونوں کو محفوظ رکھتی ہے۔", "wisdom_benefit_en": "Provides an emotional de-escalation protocol, teaching individuals to walk away peacefully from toxic provocations without losing dignity."}, {"serial": 21, "id": "cmd_021", "surah_id": 76, "ayah_num": 8, "surah_name_en": "Al Insan", "surah_name_ar": "اَلدَّهْر (اَلْاِنْسَان)", "surah_name_roman": "Al Insan", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "command", "title_ur": "محبتِ الٰہی میں مسکین، یتیم اور قیدی کو کھانا کھلاؤ", "title_en": "Feed the Indigent, Orphan, and Captive", "arabic": "وَیُطْعِمُوْنَ الطَّعَامَ عَلٰى حُبِّهٖ مِسْكِیْنًا وَّیَتِیْمًا وَّاَسِیْرًا", "translation_urdu_kanzul_iman": "اور کھانا کھلاتے ہیں  اس کی محبت پر مسکین اور یتیم اور اَ    سِیر کو۔", "translation_urdu_kanzul_irfan": "اور وہ اللہ  کی محبت میں  مسکین اور یتیم اور قیدی کوکھانا کھلاتے ہیں۔", "translation_english": "And out of His love, they feed the needy, the orphan and the prisoner.", "wisdom_benefit_ur": "بھوکوں کو کھانا کھلانا معاشرے میں غربت کی تلخی اور جرائم کی ترغیب کو مٹاتا ہے اور باہمی ہمدردی پیدا کرتا ہے۔", "wisdom_benefit_en": "Providing nutritional sustenance to vulnerable populations alleviates acute deprivation, curtails street desperation, and knits societal cohesion."}, {"serial": 22, "id": "cmd_022", "surah_id": 90, "ayah_num": 14, "surah_name_en": "Al Balad", "surah_name_ar": "اَلْبَـلَد", "surah_name_roman": "Al Balad", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "command", "title_ur": "فاقے اور قحط کے دنوں میں کھانا کھلاؤ", "title_en": "Feed During Days of Severe Hunger & Famine", "arabic": "اَوْ اِطْعٰمٌ فِیْ یَوْمٍ ذِیْ مَسْغَبَةٍۙ", "translation_urdu_kanzul_iman": "یا بھوک کے دن کھانا دینا۔", "translation_urdu_kanzul_irfan": "یا بھوک کے دن میں  کھانا دینا۔", "translation_english": "Or the feeding on a day of hunger.", "wisdom_benefit_ur": "معاشی بحران اور گرانی کے وقت غریبوں کی خبر گیری انسانیت کی سب سے بڑی خدمت اور بلندی کا زینہ ہے۔", "wisdom_benefit_en": "Urges swift emergency humanitarian food security during economic crises and famines, rescuing families from biological starvation."}, {"serial": 23, "id": "cmd_023", "surah_id": 93, "ayah_num": 9, "surah_name_en": "Ad Duha", "surah_name_ar": "اَلْضُّحٰی", "surah_name_roman": "Ad Duha", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "prohibition", "title_ur": "یتیم پر کبھی سختی یا ظلم نہ کرو", "title_en": "Do Not Oppress or Despise the Orphan", "arabic": "فَاَمَّا الْیَتِیْمَ فَلَا تَقْهَرْؕ", "translation_urdu_kanzul_iman": "تو یتیم پر دباؤ نہ ڈالو ۔", "translation_urdu_kanzul_irfan": "تو کسی بھی صورت یتیم پر سختی نہ کرو۔", "translation_english": "Therefore, do not put pressure on an orphan.", "wisdom_benefit_ur": "یتیم بچوں کی دلجوئی ان کے اندر احساسِ محرومی کو ختم کر کے انہیں معاشرے کا باوقار اور مفید شہری بناتی ہے۔", "wisdom_benefit_en": "Protecting parentless children preserves their developmental psychology, preventing trauma, delinquency, and deep-seated social alienation."}, {"serial": 24, "id": "cmd_024", "surah_id": 93, "ayah_num": 10, "surah_name_en": "Ad Duha", "surah_name_ar": "اَلْضُّحٰی", "surah_name_roman": "Ad Duha", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "prohibition", "title_ur": "سوالی اور ضرورت مند کو مت جھڑکو", "title_en": "Do Not Scold or Repulse the Petitioner", "arabic": "وَاَمَّا السَّآىٕلَ فَلَا تَنْهَرْؕ", "translation_urdu_kanzul_iman": "اور منگتا کو نہ جھڑکو ۔", "translation_urdu_kanzul_irfan": "اورکسی بھی صورت مانگنے والے کو نہ جھڑکو۔", "translation_english": "And do not scold a beggar.", "wisdom_benefit_ur": "ضرورت مند کو جھڑکنے کے بجائے یا تو حسنِ سلوک سے مدد کرو یا نرمی سے معذرت کرو تاکہ اس کی عزتِ نفس مجروح نہ ہو۔", "wisdom_benefit_en": "Forbids demeaning the impoverished; mandates either benevolent assistance or compassionate, dignified refusal without verbal humiliation."}, {"serial": 25, "id": "cmd_025", "surah_id": 107, "ayah_num": 3, "surah_name_en": "Al Maun", "surah_name_ar": "اَلْمَاعُوْن", "surah_name_roman": "Al Maun", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "prohibition", "title_ur": "مسکین کو کھانا کھلانے کی ترغیب نہ دینے سے بچو", "title_en": "Never Neglect or Discourage Feeding the Poor", "arabic": "وَلَا یَحُضُّ عَلٰى طَعَامِ الْمِسْكِیْنِؕ", "translation_urdu_kanzul_iman": "اور مسکین کو کھانا دینے کی رغبت نہیں  دیتا ۔", "translation_urdu_kanzul_irfan": "اور مسکین کو کھانا دینے کی ترغیب نہیں   دیتا۔", "translation_english": "And does not encourage (others) to feed the needy.", "wisdom_benefit_ur": "خود بھی کھانا کھلانا اور دوسروں کو بھی بھوکوں کی امداد پر آمادہ کرنا سچے ایمان اور انسان دوستی کی روح ہے۔", "wisdom_benefit_en": "Condemns passive apathy toward poverty; urges collective advocacy and institutional mobilization for hunger eradication."}, {"serial": 26, "id": "cmd_026", "surah_id": 17, "ayah_num": 26, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "command", "title_ur": "رشتہ داروں، مسکینوں اور مسافروں کو ان کا حق دو", "title_en": "Give Relatives, the Needy, and Wayfarers Their Due", "arabic": "وَاٰتِ ذَا الْقُرْبٰى حَقَّهٗ وَالْمِسْكِیْنَ وَابْنَ السَّبِیْلِ وَلَا تُبَذِّرْ تَبْذِیْرًا", "translation_urdu_kanzul_iman": "اور رشتہ داروں  کو ان کا حق دے اور مسکین اور مسافر کو اور فضول نہ اڑا۔", "translation_urdu_kanzul_irfan": "اور رشتہ داروں   کو ان کا حق دو اور مسکین اور مسافر کو (بھی دو) اور فضول خرچی نہ کرو۔", "translation_english": "And give relatives their right, and (give) to the needy and to the traveller, and do not spend wastefully.", "wisdom_benefit_ur": "مال میں غریبوں کا حق تسلیم کرنا دولت کا ارتکاز روکتا ہے اور معاشی خوشحالی کو نچلی سطح تک پہنچاتا ہے۔", "wisdom_benefit_en": "Recognizes socioeconomic welfare not as optional pity, but as an enforceable right of the destitute, redistributing societal liquidity."}, {"serial": 27, "id": "cmd_027", "surah_id": 2, "ayah_num": 264, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "prohibition", "title_ur": "احسان جتلانے اور تکلیف دینے سے اپنے صدقات ضائع نہ کرو", "title_en": "Do Not Void Charity with Reminders or Insults", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تُبْطِلُوْا صَدَقٰتِكُمْ بِالْمَنِّ وَالْاَذٰىۙ-كَالَّذِیْ یُنْفِقُ مَالَهٗ رِئَآءَ النَّاسِ وَلَا یُؤْمِنُ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِؕ-فَمَثَلُهٗ كَمَثَلِ صَفْوَانٍ عَلَیْهِ تُرَابٌ فَاَصَابَهٗ وَابِلٌ فَتَرَكَهٗ صَلْدًاؕ-لَا یَقْدِرُوْنَ عَلٰى شَیْءٍ مِّمَّا كَسَبُوْاؕ-وَاللّٰهُ لَا یَهْدِی الْقَوْمَ الْكٰفِرِیْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو اپنے صدقے باطل نہ کردو احسان رکھ کر اور ایذا دے کر اس کی طرح جو اپنا مال لوگوں کے دکھاوے کے لئے خرچ کرے اور  اللہ  اور قیامت پر ایمان نہ لائے، تو اس کی کہاوت ایسی ہے جیسے ایک چٹان کہ اس پر مٹی ہے اب اس پر زور کا پانی پڑا جس نے اسے نرا پتھر کر چھوڑا اپنی کمائی سے کسی چیز پر قابو نہ پائیں گے اور  اللہ  کافروں کو راہ نہیں دیتا۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! احسان جتا کر اور تکلیف پہنچا کر اپنے صدقے برباد نہ کردو اس شخص کی طرح جو اپنا مال لوگوں  کے دکھلاوے کے لئے خرچ کرتا ہے اور اللہ  اور قیامت پر ایمان نہیں  لاتا تو اس کی مثال ایسی ہے جیسے ایک چکنا پتھر ہوجس پر مٹی ہے تواس پر زورداربارش پڑی جس نے اسے صاف پتھر کر چھوڑا، ایسے لوگ اپنے کمائے ہوئے اعمال سے کسی چیز پر قدرت نہ پائیں  گے اور اللہ  کافروں  کوہدایت نہیں  دیتا۔", "translation_english": "O believers! Do not invalidate your charity by boasting of favours and by causing anguish, like the one who spends his wealth to show off to people, and (he) believes not in Allah and the Last Day. His example is therefore similar to that of a (smooth) rock covered with dust and thereupon heavy rain fell on it, leaving it a bare rock. They will not have control over anything they have earned, and Allah does not guide the disbelievers (due to their stubbornness upon disbelief).", "wisdom_benefit_ur": "احسان جتلانے سے خیرات کا اجر باطل ہو جاتا ہے اور لینے والے کی روح گھائل ہوتی ہے۔ بے لوث انفاق ہی حقیقی صدقہ ہے۔", "wisdom_benefit_en": "Bans emotional exploitation in philanthropy; giving must be unconditional and free of psychological superiority to safeguard human dignity."}, {"serial": 28, "id": "cmd_028", "surah_id": 3, "ayah_num": 92, "surah_name_en": "Al Imran", "surah_name_ar": "اٰلِ عِمْرَان", "surah_name_roman": "Al Imran", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "command", "title_ur": "تم نیکی کو نہیں پہنچ سکتے جب تک اپنی محبوب ترین چیز خرچ نہ کرو", "title_en": "Spend from What You Truly Love", "arabic": "لَنْ تَنَالُوا الْبِرَّ حَتّٰى تُنْفِقُوْا مِمَّا تُحِبُّوْنَ ۗ وَمَا تُنْفِقُوْا مِنْ شَیْءٍ فَاِنَّ اللّٰهَ بِهٖ عَلِیْمٌ", "translation_urdu_kanzul_iman": "تم ہرگز بھلائی کو نہ پہنچو گے جب تک راہِ خدا میں اپنی پیاری چیز نہ خرچ کرو اور تم جو کچھ خرچ کرو  اللہ  کو معلوم ہے ۔", "translation_urdu_kanzul_irfan": "تم ہرگز بھلائی کو نہیں  پا سکو گے جب تک راہِ خدا میں  اپنی پیاری چیز خرچ نہ کرو اور تم جو کچھ خرچ کرتے ہو اللہ  اسے جانتا ہے۔", "translation_english": "You shall never reach righteousness until you spend the thing you love in the way of Allah, and Allah is Aware of whatever you spend.", "wisdom_benefit_ur": "بیکار یا ردی اشیاء کے بجائے اپنی پسندیدہ چیز اللہ کی راہ میں دینا نفس کی بخل اور لالچ کو جڑ سے ختم کرتا ہے۔", "wisdom_benefit_en": "Cures materialism and hoarder psychology by encouraging individuals to detach from excessive attachment to valuable possessions."}, {"serial": 29, "id": "cmd_029", "surah_id": 2, "ayah_num": 271, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "command", "title_ur": "اگر صدقات چھپا کر غریبوں کو دو تو یہ تمہارے لیے بہت بہتر ہے", "title_en": "Give Charity Discreetly to Preserve Dignity", "arabic": "اِنْ تُبْدُوا الصَّدَقٰتِ فَنِعِمَّا هِیَۚ-وَاِنْ تُخْفُوْهَا وَتُؤْتُوْهَا الْفُقَرَآءَ فَهُوَ خَیْرٌ لَّكُمْؕ-وَیُكَفِّرُ عَنْكُمْ مِّنْ سَیِّاٰتِكُمْؕ-وَاللّٰهُ بِمَا تَعْمَلُوْنَ خَبِیْرٌ", "translation_urdu_kanzul_iman": "اگر خیرات علانیہ دو تو وہ کیا ہی اچھی بات ہے اور اگر چھپا کر فقیروں کو دو یہ تمہارے لئے سب سے بہتر ہے اور اس میں تمہارے کچھ گناہ گھٹیں گے اور  اللہ  کو تمہارے کاموں کی خبر ہے۔", "translation_urdu_kanzul_irfan": "اگر تم اعلانیہ خیرات دو گے تو وہ کیا ہی اچھی بات ہے اور اگرتم چھپا کر فقیروں  کو دو تویہ تمہارے لئے سب سے بہتر ہے اور اللہ  تم سے تمہاری کچھ برائیاں  مٹا دے گا اور اللہ  تمہارے کاموں  سے خبردار ہے۔", "translation_english": "If you give charity openly, so what an excellent thing that is; and if you give it secretly to the poor, this is better for you; and in this (way), some of your sins will reduce. And Allah is Aware of your actions.", "wisdom_benefit_ur": "پوشیدہ امداد دکھاوے اور ریاکاری سے بچاتی ہے اور لینے والے کو کسی کے سامنے شرمسار نہیں ہونے دیتی۔", "wisdom_benefit_en": "Discreet, anonymous philanthropy completely eliminates ostentation (Riya) and protects the recipient from public embarrassment."}, {"serial": 30, "id": "cmd_030", "surah_id": 107, "ayah_num": 7, "surah_name_en": "Al Maun", "surah_name_ar": "اَلْمَاعُوْن", "surah_name_roman": "Al Maun", "category_id": "compassion", "category_name_ur": "سخاوت، اطعامِ طعام اور غریب پروری", "category_name_en": "Compassion, Charity & Feeding the Vulnerable", "category_icon": "🍲", "category_color": "#f59e0b", "polarity": "prohibition", "title_ur": "عام برتنے کی چھوٹی چھوٹی چیزیں مانگے پر روکنے سے بچو", "title_en": "Do Not Withhold Everyday Basic Necessities", "arabic": "وَیَمْنَعُوْنَ الْمَاعُوْنَ۠", "translation_urdu_kanzul_iman": "اور بر تنے کی چیز مانگے نہیں  دیتے ۔", "translation_urdu_kanzul_irfan": "اور برتنے کی معمولی چیزیں   بھی نہیں   دیتے۔", "translation_english": "And refuse to give (small) things of use when asked.", "wisdom_benefit_ur": "پڑوسیوں اور ضرورت مندوں کو روزمرہ استعمال کی چھوٹی اشیاء (برتن، اوزار، نمک) دینے سے انکار سنگدلی کی علامت ہے۔", "wisdom_benefit_en": "Promotes micro-generosity and neighborly support by condemning the stingy withholding of everyday tools, utensils, and basic commodities."}, {"serial": 31, "id": "cmd_031", "surah_id": 49, "ayah_num": 12, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "prohibition", "title_ur": "کسی کی پیٹھ پیچھے غیبت مت کرو", "title_en": "Do Not Backbite One Another", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوا اجْتَنِبُوْا كَثِیْرًا مِّنَ الظَّنِّ٘-اِنَّ بَعْضَ الظَّنِّ اِثْمٌ وَّلَا تَجَسَّسُوْا وَلَا یَغْتَبْ بَّعْضُكُمْ بَعْضًاؕ-اَیُحِبُّ اَحَدُكُمْ اَنْ یَّاْكُلَ لَحْمَ اَخِیْهِ مَیْتًا فَكَرِهْتُمُوْهُؕ-وَاتَّقُوا اللّٰهَؕ-اِنَّ اللّٰهَ تَوَّابٌ رَّحِیْمٌ", "translation_urdu_kanzul_iman": "اے ایمان والو بہت گمانوں  سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور عیب نہ ڈھونڈھو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں  کوئی پسند رکھے گا کہ اپنے مرے بھائی کا گوشت کھائے تو یہ تمہیں  گوارا نہ ہوگا اور  اللہ  سے ڈرو بیشک  اللہ  بہت توبہ قبول کرنے والا مہربان ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! بہت زیادہ گمان کرنے سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور (پوشیدہ باتوں   کی) جستجو نہ کرو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں   کوئی پسند کرے گا کہ اپنے مرے ہوئے بھائی کا گوشت کھائے تو یہ تمہیں   ناپسند ہوگا اور اللہ  سے ڈرو بیشک اللہ  بہت توبہ قبول کرنے والا، مہربان ہے۔", "translation_english": "O believers! Avoid much suspicions; indeed, some suspicions become sin. And do not search for (hidden) faults, do not backbite one another; would any one amongst you like to eat the flesh of his dead brother? So, you will not tolerate this. And fear Allah; indeed, Allah is the Great Acceptor of repentance, Ever Merciful.", "wisdom_benefit_ur": "غیبت باہمی اعتماد، دوستی اور امن کو دیمک کی طرح چاٹ جاتی ہے اور معاشرے میں زہریلی عداوت پیدا کرتی ہے۔", "wisdom_benefit_en": "Backbiting destroys social capital, erodes professional trust, and breeds covert malice, toxic gossip, and interpersonal enmity."}, {"serial": 32, "id": "cmd_032", "surah_id": 49, "ayah_num": 12, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "prohibition", "title_ur": "دوسروں کی نجی زندگی میں جاسوسی اور ٹوہ مت لگاؤ", "title_en": "Do Not Spy or Pry into Private Matters", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوا اجْتَنِبُوْا كَثِیْرًا مِّنَ الظَّنِّ٘-اِنَّ بَعْضَ الظَّنِّ اِثْمٌ وَّلَا تَجَسَّسُوْا وَلَا یَغْتَبْ بَّعْضُكُمْ بَعْضًاؕ-اَیُحِبُّ اَحَدُكُمْ اَنْ یَّاْكُلَ لَحْمَ اَخِیْهِ مَیْتًا فَكَرِهْتُمُوْهُؕ-وَاتَّقُوا اللّٰهَؕ-اِنَّ اللّٰهَ تَوَّابٌ رَّحِیْمٌ", "translation_urdu_kanzul_iman": "اے ایمان والو بہت گمانوں  سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور عیب نہ ڈھونڈھو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں  کوئی پسند رکھے گا کہ اپنے مرے بھائی کا گوشت کھائے تو یہ تمہیں  گوارا نہ ہوگا اور  اللہ  سے ڈرو بیشک  اللہ  بہت توبہ قبول کرنے والا مہربان ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! بہت زیادہ گمان کرنے سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور (پوشیدہ باتوں   کی) جستجو نہ کرو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں   کوئی پسند کرے گا کہ اپنے مرے ہوئے بھائی کا گوشت کھائے تو یہ تمہیں   ناپسند ہوگا اور اللہ  سے ڈرو بیشک اللہ  بہت توبہ قبول کرنے والا، مہربان ہے۔", "translation_english": "O believers! Avoid much suspicions; indeed, some suspicions become sin. And do not search for (hidden) faults, do not backbite one another; would any one amongst you like to eat the flesh of his dead brother? So, you will not tolerate this. And fear Allah; indeed, Allah is the Great Acceptor of repentance, Ever Merciful.", "wisdom_benefit_ur": "لوگوں کے عیوب تلاش کرنا اور ان کی نجی زندگی میں جھانکنا ذاتی آزادی اور عزتِ نفس پر سنگین حملہ ہے۔", "wisdom_benefit_en": "Enshrines inviolable personal privacy, forbidding surveillance, prying into private affairs, and weaponizing hidden human faults."}, {"serial": 33, "id": "cmd_033", "surah_id": 49, "ayah_num": 12, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "prohibition", "title_ur": "بہت سی بدگمانیوں سے بچو، بیشک بعض گمان گناہ ہیں", "title_en": "Avoid Excessive & Baseless Suspicion", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوا اجْتَنِبُوْا كَثِیْرًا مِّنَ الظَّنِّ٘-اِنَّ بَعْضَ الظَّنِّ اِثْمٌ وَّلَا تَجَسَّسُوْا وَلَا یَغْتَبْ بَّعْضُكُمْ بَعْضًاؕ-اَیُحِبُّ اَحَدُكُمْ اَنْ یَّاْكُلَ لَحْمَ اَخِیْهِ مَیْتًا فَكَرِهْتُمُوْهُؕ-وَاتَّقُوا اللّٰهَؕ-اِنَّ اللّٰهَ تَوَّابٌ رَّحِیْمٌ", "translation_urdu_kanzul_iman": "اے ایمان والو بہت گمانوں  سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور عیب نہ ڈھونڈھو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں  کوئی پسند رکھے گا کہ اپنے مرے بھائی کا گوشت کھائے تو یہ تمہیں  گوارا نہ ہوگا اور  اللہ  سے ڈرو بیشک  اللہ  بہت توبہ قبول کرنے والا مہربان ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! بہت زیادہ گمان کرنے سے بچو بیشک کوئی گمان گناہ ہوجاتا ہے اور (پوشیدہ باتوں   کی) جستجو نہ کرو اور ایک دوسرے کی غیبت نہ کرو کیا تم میں   کوئی پسند کرے گا کہ اپنے مرے ہوئے بھائی کا گوشت کھائے تو یہ تمہیں   ناپسند ہوگا اور اللہ  سے ڈرو بیشک اللہ  بہت توبہ قبول کرنے والا، مہربان ہے۔", "translation_english": "O believers! Avoid much suspicions; indeed, some suspicions become sin. And do not search for (hidden) faults, do not backbite one another; would any one amongst you like to eat the flesh of his dead brother? So, you will not tolerate this. And fear Allah; indeed, Allah is the Great Acceptor of repentance, Ever Merciful.", "wisdom_benefit_ur": "منفی گمان انسان کو شکی، خوفزدہ اور اکیلا کر دیتا ہے۔ مثبت سوچ ذہنی صحت اور پرسکون تعلقات کا سرچشمہ ہے۔", "wisdom_benefit_en": "Chronic cognitive paranoia and unwarranted negative assumptions trigger acute anxiety, damage marital harmony, and destroy friendships."}, {"serial": 34, "id": "cmd_034", "surah_id": 49, "ayah_num": 11, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "prohibition", "title_ur": "کوئی قوم کسی کا مذاق نہ اڑائے، شاید وہ ان سے بہتر ہوں", "title_en": "Do Not Mock, Belittle, or Ridicule Others", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا یَسْخَرْ قَوْمٌ مِّنْ قَوْمٍ عَسٰۤى اَنْ یَّكُوْنُوْا خَیْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّنْ نِّسَآءٍ عَسٰۤى اَنْ یَّكُنَّ خَیْرًا مِّنْهُنَّۚ-وَلَا تَلْمِزُوْۤا اَنْفُسَكُمْ وَلَا تَنَابَزُوْا بِالْاَلْقَابِؕ-بِئْسَ الِاسْمُ الْفُسُوْقُ بَعْدَ الْاِیْمَانِۚ-وَمَنْ لَّمْ یَتُبْ فَاُولٰٓىٕكَ هُمُ الظّٰلِمُوْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو نہ مرد مردوں  سے ہنسیں  عجب نہیں  کہ وہ ان ہنسنے والوں  سے بہتر ہوں  اور نہ عورتیں  عورتوں  سے دُور نہیں  کہ وہ ان ہنسنے والیوں  سے بہتر ہوں  اور آپس میں  طعنہ نہ کرو اور ایک دوسرے کے بُرے نام نہ رکھو کیا ہی بُرا نام ہے مسلمان ہوکر فاسق کہلانا اور جو توبہ نہ کریں  تو وہی ظالم ہیں ۔", "translation_urdu_kanzul_irfan": "اے ایمان والو !مرد دوسرے مردوں   پر نہ ہنسیں، ہوسکتا ہے کہ وہ ان ہنسنے والوں   سے بہتر ہوں   اور نہ عورتیں   دوسری عورتوں   پر ہنسیں  ، ہوسکتا ہے کہ وہ ان ہنسنے والیوں   سے بہتر ہوں   اور آپس میں   کسی کو طعنہ نہ دو اور ایک دوسرے کے برے نام نہ رکھو، مسلمان ہونے کے بعد فاسق کہلانا کیا ہی برا نام ہے اور جو توبہ نہ کریں   تو وہی ظالم ہیں۔", "translation_english": "O believers! Men must not ridicule other men, it is likely that the ridiculed are better than the mockers; nor must the women ridicule other women, it is likely that the ridiculed women may be better than the mockers; and do not taunt one another, nor give evil nicknames. What a bad name it is to be called an evildoer after being a Muslim. And whoever does not repent, it is they who are the unjust.", "wisdom_benefit_ur": "تمسخر اور تضحیک انسان کے اعتماد کو کچل دیتی ہے اور نفسیاتی صدمے اور خودکشی کے رجحانات کا سبب بنتی ہے۔", "wisdom_benefit_en": "Bullying, social mockery, and psychological belittling inflict enduring trauma; outlawing mockery restores egalitarian respect."}, {"serial": 35, "id": "cmd_035", "surah_id": 49, "ayah_num": 11, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "prohibition", "title_ur": "ایک دوسرے پر عیب مت لگاؤ اور برے القاب سے نہ پکارو", "title_en": "Do Not Defame or Call Each Other Offensive Names", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا یَسْخَرْ قَوْمٌ مِّنْ قَوْمٍ عَسٰۤى اَنْ یَّكُوْنُوْا خَیْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّنْ نِّسَآءٍ عَسٰۤى اَنْ یَّكُنَّ خَیْرًا مِّنْهُنَّۚ-وَلَا تَلْمِزُوْۤا اَنْفُسَكُمْ وَلَا تَنَابَزُوْا بِالْاَلْقَابِؕ-بِئْسَ الِاسْمُ الْفُسُوْقُ بَعْدَ الْاِیْمَانِۚ-وَمَنْ لَّمْ یَتُبْ فَاُولٰٓىٕكَ هُمُ الظّٰلِمُوْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو نہ مرد مردوں  سے ہنسیں  عجب نہیں  کہ وہ ان ہنسنے والوں  سے بہتر ہوں  اور نہ عورتیں  عورتوں  سے دُور نہیں  کہ وہ ان ہنسنے والیوں  سے بہتر ہوں  اور آپس میں  طعنہ نہ کرو اور ایک دوسرے کے بُرے نام نہ رکھو کیا ہی بُرا نام ہے مسلمان ہوکر فاسق کہلانا اور جو توبہ نہ کریں  تو وہی ظالم ہیں ۔", "translation_urdu_kanzul_irfan": "اے ایمان والو !مرد دوسرے مردوں   پر نہ ہنسیں، ہوسکتا ہے کہ وہ ان ہنسنے والوں   سے بہتر ہوں   اور نہ عورتیں   دوسری عورتوں   پر ہنسیں  ، ہوسکتا ہے کہ وہ ان ہنسنے والیوں   سے بہتر ہوں   اور آپس میں   کسی کو طعنہ نہ دو اور ایک دوسرے کے برے نام نہ رکھو، مسلمان ہونے کے بعد فاسق کہلانا کیا ہی برا نام ہے اور جو توبہ نہ کریں   تو وہی ظالم ہیں۔", "translation_english": "O believers! Men must not ridicule other men, it is likely that the ridiculed are better than the mockers; nor must the women ridicule other women, it is likely that the ridiculed women may be better than the mockers; and do not taunt one another, nor give evil nicknames. What a bad name it is to be called an evildoer after being a Muslim. And whoever does not repent, it is they who are the unjust.", "wisdom_benefit_ur": "نام بگاڑنا اور طعنہ زنی کرنا رشتوں میں زہر گھولتا ہے۔ اچھے ناموں سے پکارنا محبت و اپنائیت کو بڑھاتا ہے۔", "wisdom_benefit_en": "Name-calling, body shaming, and derogatory labeling cause acute emotional distress; respectful address fosters positive self-worth."}, {"serial": 36, "id": "cmd_036", "surah_id": 49, "ayah_num": 6, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "command", "title_ur": "اگر کوئی فاسق خبر لائے تو تحقیق کر لو تاکہ بے گناہوں کو نقصان نہ پہنچے", "title_en": "Verify Information Before Reacting to Rumors", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اِنْ جَآءَكُمْ فَاسِقٌۢ بِنَبَاٍ فَتَبَیَّنُوْۤا اَنْ تُصِیْبُوْا قَوْمًۢا بِجَهَالَةٍ فَتُصْبِحُوْا عَلٰى مَا فَعَلْتُمْ نٰدِمِیْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو اگر کوئی فاسق تمہارے پاس کوئی خبر لائے تو تحقیق کرلو کہ کہیں  کسی قوم کو بے جانے ایذا نہ دے بیٹھو پھر اپنے کئے پر پچھتاتے رہ جاؤ۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! اگر کوئی فاسق تمہارے پاس کوئی خبر لائے تو تحقیق کرلو کہ کہیں   کسی قوم کوانجانے میں   تکلیف نہ دے بیٹھو پھر اپنے کئے پر شرمندہ ہونا پڑے۔", "translation_english": "O believers! If any sinner brings you some news, so you must investigate (it) in case you unknowingly cause suffering to some people then (later on) remain regretful for what you have done.", "wisdom_benefit_ur": "سوشل میڈیا اور افواہوں کے دور میں بغیر تصدیق خبر پھیلانا فسادات، فتنوں اور معصوم جانوں کے زیاں کا باعث بنتا ہے۔", "wisdom_benefit_en": "Mandates empirical epistemological rigor and fact-checking, preventing destructive mob psychology, misinformation, and panic."}, {"serial": 37, "id": "cmd_037", "surah_id": 49, "ayah_num": 10, "surah_name_en": "Al Hujurat", "surah_name_ar": "اَلْحُجُرٰت", "surah_name_roman": "Al Hujurat", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "command", "title_ur": "مسلمان آپس میں بھائی ہیں، پس اپنے بھائیوں میں صلح کراؤ", "title_en": "Reconcile Between Brothers in Dispute", "arabic": "اِنَّمَا الْمُؤْمِنُوْنَ اِخْوَةٌ فَاَصْلِحُوْا بَیْنَ اَخَوَیْكُمْ وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُرْحَمُوْنَ۠", "translation_urdu_kanzul_iman": "مسلمان مسلمان بھائی ہیں  تو اپنے دو بھائیوں  میں  صلح کرو اور  اللہ  سے ڈرو کہ تم پر رحمت ہو۔", "translation_urdu_kanzul_irfan": "صرف مسلمان بھائی بھائی ہیں   تو اپنے دو بھائیوں   میں   صلح کرادو اور اللہ  سے ڈروتا کہ تم پر رحمت ہو۔", "translation_english": "The Muslims are brothers (to each other), therefore make peace between your two brothers, and fear Allah, that you may attain mercy.", "wisdom_benefit_ur": "جھگڑوں کو طول دینے کے بجائے فوری ثالثی اور صلح خاندانوں اور قوموں کو ٹوٹنے سے بچاتی ہے۔", "wisdom_benefit_en": "Proactive dispute resolution and restorative justice heal fractured communities before conflicts escalate into violence."}, {"serial": 38, "id": "cmd_038", "surah_id": 4, "ayah_num": 86, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "command", "title_ur": "جب تمہیں سلام کیا جائے تو اس سے بہتر یا کم از کم ویسا ہی جواب دو", "title_en": "Return Greetings with Equal or Better Courtesy", "arabic": "وَاِذَا حُیِّیْتُمْ بِتَحِیَّةٍ فَحَیُّوْا بِاَحْسَنَ مِنْهَاۤ اَوْ رُدُّوْهَاؕ-اِنَّ اللّٰهَ كَانَ عَلٰى كُلِّ شَیْءٍ حَسِیْبًا", "translation_urdu_kanzul_iman": "اور جب تمہیں کوئی کسی لفظ سے سلام کرے تو تم اس سے بہتر لفظ جواب میں کہو یا وہی کہہ دو بے شک  اللہ  ہر چیز پر حساب لینے والا ہے۔", "translation_urdu_kanzul_irfan": "اور جب تمہیں  کسی لفظ سے سلام کیا جائے تو تم اس سے بہتر لفظ سے جواب دو یا وہی الفاظ کہہ دو۔ بیشک اللہ  ہر چیز پر حساب لینے والا ہے۔", "translation_english": "And when someone greets you with some words (of greeting), respond therefore with words better than that or return the same; indeed, Allah is going to take account of everything.", "wisdom_benefit_ur": "سلام کا پرجوش جواب اجنبیت اور سرد مہری کی برف پگھلا دیتا ہے اور دلوں میں خیر سگالی پیدا کرتا ہے۔", "wisdom_benefit_en": "Active reciprocal warmth in social greetings elevates daily communal mood and breaks down barriers of social isolation."}, {"serial": 39, "id": "cmd_039", "surah_id": 24, "ayah_num": 27, "surah_name_en": "An Noor", "surah_name_ar": "اَلنُّوْر", "surah_name_roman": "An Noor", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "command", "title_ur": "دوسروں کے گھروں میں اجازت لیے بغیر اور سلام کیے بغیر داخل نہ ہو", "title_en": "Seek Permission and Greet Before Entering Homes", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تَدْخُلُوْا بُیُوْتًا غَیْرَ بُیُوْتِكُمْ حَتّٰى تَسْتَاْنِسُوْا وَتُسَلِّمُوْا عَلٰۤى اَهْلِهَاؕ-ذٰلِكُمْ خَیْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُوْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو اپنے گھروں  کے سوا اور گھروں  میں  نہ جاؤ جب تک اجازت نہ لے لو اور ان کے ساکِنوں  پر سلام نہ کرلو یہ تمہارے لیے بہتر ہے کہ تم دھیان کرو۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! اپنے گھروں   کے سوا اور گھروں   میں   داخل نہ ہو جب تک اجازت نہ لے لو اور ان میں   رہنے والوں  پر سلام نہ کرلو۔ یہ تمہارے لیے بہتر ہے تاکہ تم نصیحت مان لو۔", "translation_english": "O believers! Do not enter the houses except your own, until you have obtained permission and have conveyed Salaam to its residents; this is better for you, that you may ponder.", "wisdom_benefit_ur": "گھر انسان کا محفوظ قلعہ ہے۔ اچانک گھسنے سے گھریلو راز فاش ہوتے ہیں اور خواتین و بچوں کی پرائیویسی پامال ہوتی ہے۔", "wisdom_benefit_en": "Domestic sanctum protocol ensures that homeowners maintain autonomy, privacy, and readiness before welcoming external visitors."}, {"serial": 40, "id": "cmd_040", "surah_id": 24, "ayah_num": 28, "surah_name_en": "An Noor", "surah_name_ar": "اَلنُّوْر", "surah_name_roman": "An Noor", "category_id": "social_peace", "category_name_ur": "معاشرتی امن، پردہ داری اور اخوت", "category_name_en": "Social Peace, Privacy & Anti-Toxicity", "category_icon": "🤝", "category_color": "#a855f7", "polarity": "command", "title_ur": "اگر کہا جائے کہ واپس لوٹ جاؤ تو خوش دلی سے لوٹ جاؤ", "title_en": "Gracefully Turn Back if Asked to Return", "arabic": "فَاِنْ لَّمْ تَجِدُوْا فِیْهَاۤ اَحَدًا فَلَا تَدْخُلُوْهَا حَتّٰى یُؤْذَنَ لَكُمْۚ-وَاِنْ قِیْلَ لَكُمُ ارْجِعُوْا فَارْجِعُوْا هُوَ اَزْكٰى لَكُمْؕ-وَاللّٰهُ بِمَا تَعْمَلُوْنَ عَلِیْمٌ", "translation_urdu_kanzul_iman": "پھر اگر ان میں  کسی کو نہ پاؤ جب بھی بے ما لکوں  کی اجازت کے ان میں  نہ جاؤ اور اگر تم سے کہا جائے واپس جاؤ تو واپس ہو یہ تمہارے لیے بہت ستھرا ہے   اللہ  تمہارے کاموں  کو جانتا ہے۔", "translation_urdu_kanzul_irfan": "پھر اگرتم ان گھروں  میں   کسی کو نہ پاؤتو بھی ان میں   داخل نہ ہو ناجب تک تمہیں   اجازت نہ دیدی جائے اور اگر تمہیں   کہا جائے ’’واپس لوٹ جاؤ ‘‘تو تم واپس لوٹ جاؤ،یہ تمہارے لیے زیادہ پاکیزہ ہے اور  اللہ  تمہارے کاموں   کو خوب جاننے والا ہے۔", "translation_english": "And if you do not find anyone in them, even then do not enter it without the permission of (their) owners. And if you are told, 'Go back,' then go back; this is much purer for you. Allah knows your deeds.", "wisdom_benefit_ur": "میزبان کی معذرت کو انا کا مسئلہ نہ بنانا بلکہ اس کی مجبوری کا احترام کرنا بلند ترین معاشرتی تہذیب ہے۔", "wisdom_benefit_en": "Respects the psychological bandwidth of hosts without taking offense, fostering mature boundaries in interpersonal relationships."}, {"serial": 41, "id": "cmd_041", "surah_id": 2, "ayah_num": 153, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "صبر اور نماز کے ذریعے اللہ سے مدد طلب کرو", "title_en": "Seek Help Through Steadfast Patience & Prayer", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوا اسْتَعِیْنُوْا بِالصَّبْرِ وَالصَّلٰوةِؕ-اِنَّ اللّٰهَ مَعَ الصّٰبِرِیْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو صبر اور نماز سے مدد چاہو بیشک  اللہ  صابروں کے ساتھ ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! صبر اور نمازسے مدد مانگو، بیشک اللہ  صابروں  کے ساتھ ہے۔", "translation_english": "O believers! Seek help from patience and Salah; indeed, Allah is with those who are patient.", "wisdom_benefit_ur": "نماز کی دلی حضوری اور مشکلات میں ضبطِ نفس اضطراب، ڈیپریشن اور خوف کا حتمی روحانی و نفسیاتی علاج ہے۔", "wisdom_benefit_en": "Combines cognitive emotional regulation (Sabr) with somatic meditative mindfulness (Salah), lowering cortisol and building neuro-resilience."}, {"serial": 42, "id": "cmd_042", "surah_id": 39, "ayah_num": 53, "surah_name_en": "Az Zumar", "surah_name_ar": "اَلزُّمَر", "surah_name_roman": "Az Zumar", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "prohibition", "title_ur": "اللہ کی رحمت سے کبھی مایوس نہ ہو", "title_en": "Do Not Despair of the Infinite Mercy of Allah", "arabic": "قُلْ یٰعِبَادِیَ الَّذِیْنَ اَسْرَفُوْا عَلٰۤى اَنْفُسِهِمْ لَا تَقْنَطُوْا مِنْ رَّحْمَةِ اللّٰهِؕ-اِنَّ اللّٰهَ یَغْفِرُ الذُّنُوْبَ جَمِیْعًاؕ-اِنَّهٗ هُوَ الْغَفُوْرُ الرَّحِیْمُ", "translation_urdu_kanzul_iman": "تم فرماؤ اے میرے وہ بندو جنہوں  نے اپنی جانوں  پر زیادتی کی  اللہ  کی رحمت سے نااُمید نہ ہو بیشک  اللہ  سب گناہ بخش دیتا ہے بیشک وہی بخشنے والا مہربان ہے۔", "translation_urdu_kanzul_irfan": "تم فرماؤ :اے میرے وہ بندو جنہوں   نے اپنی جانوں   پر زیادتی کی! اللہ  کی رحمت سے مایوس نہ ہونا ، بیشک اللہ  سب گناہ بخش دیتا ہے ،بیشک وہی بخشنے والا مہربان ہے۔", "translation_english": "Say you (O Beloved), 'O those bondsmen of mine who have committed excess upon their own souls (by committing sins), do not lose hope in the Mercy of Allah. Indeed, Allah forgives all sins (for the one who abstains from disbelief and repent thereafter); indeed, only He is the Most Forgiving, the Most Merciful.'", "wisdom_benefit_ur": "مایوسی انسان کو اندر سے کھوکھلا کر کے خودکشی کی طرف دھکیلتی ہے۔ رحمتِ الٰہی پر یقین امید کا لافانی چراغ ہے۔", "wisdom_benefit_en": "Inoculates against clinical despair and guilt-driven hopelessness, providing an open gateway to emotional renewal and psychic redemption."}, {"serial": 43, "id": "cmd_043", "surah_id": 3, "ayah_num": 134, "surah_name_en": "Al Imran", "surah_name_ar": "اٰلِ عِمْرَان", "surah_name_roman": "Al Imran", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "غصہ پی جانے والے اور لوگوں کو معاف کرنے والے بنو", "title_en": "Restrain Anger and Freely Forgive People", "arabic": "الَّذِیْنَ یُنْفِقُوْنَ فِی السَّرَّآءِ وَالضَّرَّآءِ وَالْـكٰظِمِیْنَ الْغَیْظَ وَالْعَافِیْنَ عَنِ النَّاسِؕ-وَاللّٰهُ یُحِبُّ الْمُحْسِنِیْنَۚ", "translation_urdu_kanzul_iman": "وہ جو  اللہ  کی راہ میں خرچ کرتے ہیں خوشی میں اور رنج میں اور غصہ پینے والے اور لوگوں سے درگزر کرنے والے اور نیک لوگ  اللہ  کے محبوب ہیں۔", "translation_urdu_kanzul_irfan": "وہ جو خوشحالی اور تنگدستی میں  اللہ  کی راہ میں  خرچ کرتے ہیں  اور غصہ پینے والے اور لوگوں  سے درگزر کرنے والے ہیں  اور اللہ  نیک لوگوں  سے محبت فرماتا ہے۔", "translation_english": "(They are) those who spend in the Path of Allah in prosperity and adversity, and who restrain anger and forgive people. And the righteous people are the beloveds of Allah.", "wisdom_benefit_ur": "غصہ قابو میں رکھنا ہارٹ اٹیک اور برین ہیمرج سے بچاتا ہے اور معاف کر دینے سے دل بغض کے بوجھ سے آزاد ہو جاتا ہے۔", "wisdom_benefit_en": "Anger management prevents acute cardiovascular stress; practicing active forgiveness releases toxic chronic emotional grudges."}, {"serial": 44, "id": "cmd_044", "surah_id": 3, "ayah_num": 159, "surah_name_en": "Al Imran", "surah_name_ar": "اٰلِ عِمْرَان", "surah_name_roman": "Al Imran", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "جب تم عزم کر لو تو اللہ پر بھروسہ رکھو (توکل)", "title_en": "Put Full Trust in Allah Once Resolved", "arabic": "فَبِمَا رَحْمَةٍ مِّنَ اللّٰهِ لِنْتَ لَهُمْۚ-وَلَوْ كُنْتَ فَظًّا غَلِیْظَ الْقَلْبِ لَا نْفَضُّوْا مِنْ حَوْلِكَ۪- فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِی الْاَمْرِۚ-فَاِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللّٰهِؕ-اِنَّ اللّٰهَ یُحِبُّ الْمُتَوَكِّلِیْنَ", "translation_urdu_kanzul_iman": "تو کیسی کچھ  اللہ  کی مہربانی ہے کہ اے محبوب تم ان کے لئے نرم دل ہوئے اور اگر تند مزاج سخت دل ہوتے تو وہ ضرور تمہارے گرد سے پریشان ہوجاتے تو تم انہیں معاف فرماؤ اور ان کی شفاعت کرو اور کاموں میں ان سے مشورہ لو اور جو کسی بات کا ارادہ پکا کرلو تو  اللہ  پر بھروسہ کرو بیشک توکل والے  اللہ  کو پیارے ہیں۔", "translation_urdu_kanzul_irfan": "تو اے حبیب! اللہ کی کتنی بڑی مہربانی ہے کہ آپ ان کے لئے نرم دل ہیں  اور اگر آپ تُرش مزاج ، سخت دل ہوتے تو یہ لوگ ضرورآپ کے پاس سے بھاگ جاتے توآپ ان کو معاف فرماتے رہو اوران کی مغفرت کی دعا کرتے رہو اور کاموں  میں  ان سے مشورہ لیتے رہو پھرجب کسی بات کا پختہ ارادہ کرلو تواللہ پر بھروسہ کرو بیشک اللہ توکل کرنے والوں  سے محبت فرماتا ہے ۔", "translation_english": "So, what a great mercy it is from Allah that, O Beloved, you became soft-hearted towards them. And if you had been harsh and hard-hearted, they would have therefore certainly been anxious in your surrounding; so forgive them, and intercede for them and consult with them in matters. And when you come to a firm decision regarding any matter, so have trust in Allah; indeed, Allah loves those who have trust (in Him).", "wisdom_benefit_ur": "تمام تدابیر اختیار کرنے کے بعد نتیجہ اللہ پر چھوڑ دینا وہمی وسوسوں، حد سے زیادہ سوچنے (اوور تھنکنگ) اور بے چینی کو ختم کرتا ہے۔", "wisdom_benefit_en": "Decision paralysis and post-decision anxiety are resolved through Tawakkul (spiritual surrender after rigorous effort), stabilizing the psyche."}, {"serial": 45, "id": "cmd_045", "surah_id": 13, "ayah_num": 28, "surah_name_en": "Ar Rad", "surah_name_ar": "اَلرَّعْد", "surah_name_roman": "Ar Rad", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "خبردار! اللہ کے ذکر سے ہی دلوں کو اطمینان حاصل ہوتا ہے", "title_en": "Find Rest and Serenity in the Remembrance of Allah", "arabic": "اَلَّذِیْنَ اٰمَنُوْا وَتَطْمَىٕنُّ قُلُوْبُهُمْ بِذِكْرِ اللّٰهِؕ-اَلَا بِذِكْرِ اللّٰهِ تَطْمَىٕنُّ الْقُلُوْبُؕ", "translation_urdu_kanzul_iman": "وہ جو ایمان لائے اور ان کے دل اللہ کی یاد سے چین پاتے ہیں  سن لو اللہ کی یاد ہی میں  دلوں  کا چین ہے۔", "translation_urdu_kanzul_irfan": "۔(ان لوگوں   کو ہدایت دیتا ہے) جو ایمان لائے اور ان کے دل اللہ  کی یاد سے چین پاتے ہیں  ، سن لو! اللہ  کی یاد ہی سے دل چین پاتے ہیں  ۔", "translation_english": "'Those who accepted faith and whose hearts find satisfaction in the remembrance of Allah. Pay heed! Only in the remembrance of Allah is the satisfaction of hearts.'", "wisdom_benefit_ur": "اللہ کی یاد اور تسبیح دل کی دھڑکن اور اعصابی تناؤ کو پرسکون کر کے حقیقی اور دیرپا اندرونی مسرت فراہم کرتی ہے۔", "wisdom_benefit_en": "Sacred mindfulness and Dhikr downregulate the sympathetic nervous system, shifting brainwave patterns into profound restorative equilibrium."}, {"serial": 46, "id": "cmd_046", "surah_id": 4, "ayah_num": 32, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "prohibition", "title_ur": "جس چیز میں اللہ نے دوسروں کو فضیلت دی اس کی ہوس اور حسد نہ کرو", "title_en": "Do Not Envy What Others Have Been Favored With", "arabic": "وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللّٰهُ بِهٖ بَعْضَكُمْ عَلٰى بَعْضٍؕ-لِلرِّجَالِ نَصِیْبٌ مِّمَّا اكْتَسَبُوْاؕ-وَلِلنِّسَآءِ نَصِیْبٌ مِّمَّا اكْتَسَبْنَؕ-وَسْــٴَـلُوا اللّٰهَ مِنْ فَضْلِهٖؕ-اِنَّ اللّٰهَ كَانَ بِكُلِّ شَیْءٍ عَلِیْمًا", "translation_urdu_kanzul_iman": "اور ا س کی آرزو نہ کرو جس سے  اللہ  نے تم میں ایک کو دوسرے پر بڑائی دی مردوں کے لیے ان کی کمائی سے حصہ ہے اور عورتوں کے لیے ان کی کمائی سے حصہ اور اللہ  سے اس کا فضل مانگو بے شک  اللہ  سب کچھ جانتا ہے۔", "translation_urdu_kanzul_irfan": "اور تم ا س چیز کی تمنا نہ کرو جس سے اللہ  نے تم میں  ایک کو دوسرے پرفضیلت دی ہے ۔ مردوں  کے لئے ان کے اعمال سے حصہ ہے، اور عورتوں  کے لئے ان کے اعمال سے حصہ ہے اوراللہ  سے اس کا فضل مانگو ۔ بیشک اللہ  ہر شے کو جاننے والا ہے۔", "translation_english": "And do not long for things by which Allah has given superiority to some of you over others; for men there is a share from their earning, and for women there is a share from their earning, and ask Allah for His Bounty. Indeed, Allah knows everything.", "wisdom_benefit_ur": "حسد انسان کو اندر سے جلا کر راکھ کر دیتا ہے۔ دوسروں کی نعمتوں پر خوش ہونا اور اللہ سے اس کا فضل مانگنا سکون کی کلید ہے۔", "wisdom_benefit_en": "Envy triggers chronic neuro-emotional distress; eradicating social comparison fosters authentic gratitude and contentment."}, {"serial": 47, "id": "cmd_047", "surah_id": 9, "ayah_num": 40, "surah_name_en": "At Taubah", "surah_name_ar": "اَلتَّوْبَة", "surah_name_roman": "At Taubah", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "غم نہ کھاؤ، بیشک اللہ ہمارے ساتھ ہے", "title_en": "Do Not Grieve; Indeed, Allah Is with Us", "arabic": "اِلَّا تَنْصُرُوْهُ فَقَدْ نَصَرَهُ اللّٰهُ اِذْ اَخْرَجَهُ الَّذِیْنَ كَفَرُوْا ثَانِیَ اثْنَیْنِ اِذْ هُمَا فِی الْغَارِ اِذْ یَقُوْلُ لِصَاحِبِهٖ لَا تَحْزَنْ اِنَّ اللّٰهَ مَعَنَاۚ-فَاَنْزَلَ اللّٰهُ سَكِیْنَتَهٗ عَلَیْهِ وَاَیَّدَهٗ بِجُنُوْدٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ الَّذِیْنَ كَفَرُوا السُّفْلٰىؕ-وَكَلِمَةُ اللّٰهِ هِیَ الْعُلْیَاؕ-وَاللّٰهُ عَزِیْزٌ حَكِیْمٌ", "translation_urdu_kanzul_iman": "اگر تم محبوب کی مدد نہ کرو  تو بیشک  اللہ نے ان کی مدد فرمائی جب کافروں کی شرارت سے  انہیں باہر تشریف لے جانا ہوا صرف دو جان سے  جب وہ دونوں غار میں تھے  جب اپنے یار سے فرماتے تھے غم نہ کھا بیشک  اللہ  ہمارے ساتھ ہے  تو  اللہ  نے اس پر اپنا سکینہ اتارا اور ان فوجوں سے اس کی مدد کی جو تم نے نہ دیکھیں اور کافروں کی بات نیچے ڈالی  اللہ  ہی کا بول بالا ہے  اور  اللہ  غالب حکمت والا ہے۔", "translation_urdu_kanzul_irfan": "اگر تم اس (نبی) کی مدد نہیں  کرو گے تو اللہ  ان کی مدد فرماچکا ہے جب کافروں  نے انہیں  (ان کے وطن سے) نکال دیا تھا جبکہ یہ دو میں  سے دوسرے تھے، جب دونوں  غار میں  تھے، جب یہ اپنے ساتھی سے فرما رہے تھے غم نہ کرو، بیشک اللہ  ہمارے ساتھ ہے تو اللہ  نے اُس پر اپنی تسکین نازل فرمائی اور اُن لشکروں  کے ساتھ اُس کی مدد فرمائی جو تم نے نہ دیکھے اور اُس نے کافروں  کی بات کو نیچے کردیا اور اللہ  کی بات ہی بلندو بالا ہے اور اللہ  غالب حکمت والا ہے۔", "translation_english": "If you do not help the Beloved (Prophet Muhammad), Allah has henceforth indeed (already) helped him when he had to go out (for migration) due to the mischief of the disbelievers, (being the second of) just two souls when they were in the cave, when he was saying to his friend (i.e. Sayyiduna Abu Bakr), 'Do not grieve; indeed, Allah is with us.' So, Allah sent down His tranquillity upon him and helped him with armies you did not see, and deteriorated the word of the disbelievers; Allah's Word is supreme; and Allah is Overpowering, Ever Wise.", "wisdom_benefit_ur": "تنہائی، بے سروسامانی اور بحران کے عالم میں خدا کی معیت کا یقین تنہائی کے خوف کو شجاعت اور سکینت میں بدل دیتا ہے۔", "wisdom_benefit_en": "Transcendent divine presence dispels the terror of isolation during existential crises, imparting unshakeable courage."}, {"serial": 48, "id": "cmd_048", "surah_id": 70, "ayah_num": 5, "surah_name_en": "Al Maarij", "surah_name_ar": "اَلْمَعَارِ ج", "surah_name_roman": "Al Maarij", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "پس خوبصورتی کے ساتھ صبر کرو (صبرِ جمیل)", "title_en": "Endure with Beautiful, Uncomplaining Patience", "arabic": "فَاصْبِرْ صَبْرًا جَمِیْلًا", "translation_urdu_kanzul_iman": "تو تم اچھی طرح صبر کرو۔", "translation_urdu_kanzul_irfan": "تو تم اچھی طرح صبر کرو۔", "translation_english": "Therefore (O Beloved), be admirably patient.", "wisdom_benefit_ur": "واویلا مچائے بغیر باوقار صبر انسان کے اخلاق کو کندن بنا دیتا ہے اور اسے ہر امتحان میں سرخرو کرتا ہے۔", "wisdom_benefit_en": "Cultivates graceful fortitude (Sabrun Jameel), enabling individuals to withstand severe grief without disintegrating emotionally."}, {"serial": 49, "id": "cmd_049", "surah_id": 42, "ayah_num": 37, "surah_name_en": "Ash Shura", "surah_name_ar": "اَلشُّوْرٰی", "surah_name_roman": "Ash Shura", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "command", "title_ur": "جب انہیں غصہ آئے تو وہ معاف کر دیتے ہیں", "title_en": "Forgive Readily When Provoked to Wrath", "arabic": "وَالَّذِیْنَ یَجْتَنِبُوْنَ كَبٰٓىٕرَ الْاِثْمِ وَالْفَوَاحِشَ وَاِذَا مَا غَضِبُوْا هُمْ یَغْفِرُوْنَۚ", "translation_urdu_kanzul_iman": "اور وہ جو بڑے بڑے گناہوں  اور بے حیائیوں  سے بچتے ہیں  اور جب غصہ آئے معاف کردیتے ہیں ۔", "translation_urdu_kanzul_irfan": "اور(ان کیلئے) جو بڑے بڑے گناہوں   اور بے حیائی کے کاموں   سے اجتناب کرتے ہیں   اور جب انہیں   غصہ آئے تومعاف کردیتے ہیں  ۔", "translation_english": "And (for) those who avoid major sins, and indecencies, and forgive when they are angry.", "wisdom_benefit_ur": "اشتعال کے عروج پر معاف کر دینا انتقامی آگ کو بجھا دیتا ہے اور انسان کو باطنی طاقت و سکون بخشتا ہے۔", "wisdom_benefit_en": "Transforming impulsive rage into conscious clemency prevents destructive violent actions and restores autonomic balance."}, {"serial": 50, "id": "cmd_050", "surah_id": 59, "ayah_num": 10, "surah_name_en": "Al Hashr", "surah_name_ar": "اَلْحَشْر", "surah_name_roman": "Al Hashr", "category_id": "mental_peace", "category_name_ur": "ذہنی سکون، صبر اور امید", "category_name_en": "Mental Peace, Emotional Resilience & Patience", "category_icon": "🧠", "category_color": "#06b6d4", "polarity": "prohibition", "title_ur": "ہمارے دلوں میں اہل ایمان کے خلاف کینہ مت رکھ", "title_en": "Purge Your Heart of Resentment and Malice", "arabic": "وَالَّذِیْنَ جَآءُوْ مِنْۢ بَعْدِهِمْ یَقُوْلُوْنَ رَبَّنَا اغْفِرْ لَنَا وَلِاِخْوَانِنَا الَّذِیْنَ سَبَقُوْنَا بِالْاِیْمَانِ وَلَا تَجْعَلْ فِیْ قُلُوْبِنَا غِلًّا لِّلَّذِیْنَ اٰمَنُوْا رَبَّنَاۤ اِنَّكَ رَءُوْفٌ رَّحِیْمٌ۠", "translation_urdu_kanzul_iman": "اور وہ جو اُن کے بعد آئے عرض کرتے ہیں  اے ہمارے رب ہمیں  بخش دے اور ہمارے بھائیوں  کو جو ہم سے پہلے ایمان لائے اور ہمارے دل میں  ایمان والوں  کی طرف سے کینہ نہ رکھ اے رب ہمارے بے شک تو ہی نہایت مہربان رحم والا ہے۔", "translation_urdu_kanzul_irfan": "اوران کے بعد آنے والے عرض کرتے ہیں  : اے ہمارے رب! ہمیں   اورہمارے ان بھائیوں   کوبخش دے جو ہم سے پہلے ایمان لائے اور ہمارے دل میں   ایمان والوں   کیلئے کوئی کینہ نہ رکھ، اے ہمارے رب! بیشک تو نہایت مہربان، بہت رحمت والا ہے۔", "translation_english": "And those who came after them submit, 'O our Lord, forgive us and our brothers who accepted faith before us, and place not any malice in our hearts towards the believers. O our Lord, only You are indeed Most Compassionate, Most Merciful.'", "wisdom_benefit_ur": "دل میں دوسروں کے خلاف بغض و کینہ رکھنا انسان کی نیند اور ہاضمے کو خراب کرتا ہے۔ دل صاف رکھنے والا سب سے پرسکون رہتا ہے۔", "wisdom_benefit_en": "Resentment and bitterness release chronic inflammatory cytokines; maintaining an unburdened, pure heart preserves psychosomatic health."}, {"serial": 51, "id": "cmd_051", "surah_id": 17, "ayah_num": 35, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "command", "title_ur": "جب ناپو تو پورا ناپو اور سیدھی ترازو سے تولو", "title_en": "Give Full Measure & Weigh with Just Scales", "arabic": "وَاَوْفُوا الْكَیْلَ اِذَا كِلْتُمْ وَزِنُوْا بِالْقِسْطَاسِ الْمُسْتَقِیْمِؕ-ذٰلِكَ خَیْرٌ وَّاَحْسَنُ تَاْوِیْلًا", "translation_urdu_kanzul_iman": "اور ماپو تو پورا ماپو اور برابر ترازو سے تولویہ بہتر ہے اور اس کا انجام اچھا۔", "translation_urdu_kanzul_irfan": "اور جب ناپ کرو تو پورا ناپ کرو اور بالکل صحیح ترازو سے وزن کرو ۔یہ بہتر ہے اور انجام کے اعتبار سے اچھا ہے۔", "translation_english": "And (when) you measure, measure fully, and weigh correctly with the scale; this is better, and its outcome is good.", "wisdom_benefit_ur": "دیانتدارانہ ناپ تول مارکیٹ میں گاہک کا اعتماد قائم کرتا ہے، جبکہ ڈنڈی مارنا معیشت اور معاشرتی برکت کو برباد کر دیتا ہے۔", "wisdom_benefit_en": "Strict metrological accuracy in trade creates reliable consumer confidence, eliminates fraudulent arbitrage, and secures societal blessings."}, {"serial": 52, "id": "cmd_052", "surah_id": 83, "ayah_num": 1, "surah_name_en": "Al Mutaffifin", "surah_name_ar": "اَلْمُطَفِّفِيْن", "surah_name_roman": "Al Mutaffifin", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "prohibition", "title_ur": "ہلاکت ہے ناپ تول میں کمی کرنے والوں کے لیے", "title_en": "Woe to Those Who Give Short Measure & Defraud", "arabic": "وَیْلٌ لِّلْمُطَفِّفِیْنَۙ", "translation_urdu_kanzul_iman": "کم تولنے والوں  کی خرابی ہے", "translation_urdu_kanzul_irfan": "کم تولنے والوں   کے لئے خرابی ہے۔", "translation_english": "Destruction is for those who weigh short.", "wisdom_benefit_ur": "گاہک سے لیتے وقت پورا لینا اور دیتے وقت کم دینا چوری کی بدترین شکل ہے جس سے قوموں پر افلاس اور قحط مسلط ہوتا ہے۔", "wisdom_benefit_en": "Condemns asymmetric transactional cheating where vendors demand full payment while delivering compromised quantities."}, {"serial": 53, "id": "cmd_053", "surah_id": 2, "ayah_num": 275, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "prohibition", "title_ur": "سود (ربا) قطعی مت کھاؤ، اللہ نے تجارت حلال اور سود حرام کیا ہے", "title_en": "Never Consume Usury (Riba) — Trade Is Halal", "arabic": "اَلَّذِیْنَ یَاْكُلُوْنَ الرِّبٰوا لَا یَقُوْمُوْنَ اِلَّا كَمَا یَقُوْمُ الَّذِیْ یَتَخَبَّطُهُ الشَّیْطٰنُ مِنَ الْمَسِّؕ-ذٰلِكَ بِاَنَّهُمْ قَالُوْۤا اِنَّمَا الْبَیْعُ مِثْلُ الرِّبٰواۘ-وَاَحَلَّ اللّٰهُ الْبَیْعَ وَحَرَّمَ الرِّبٰواؕ-فَمَنْ جَآءَهٗ مَوْعِظَةٌ مِّنْ رَّبِّهٖ فَانْتَهٰى فَلَهٗ مَا سَلَفَؕ-وَاَمْرُهٗۤ اِلَى اللّٰهِؕ-وَمَنْ عَادَ فَاُولٰٓىٕكَ اَصْحٰبُ النَّارِۚ-هُمْ فِیْهَا خٰلِدُوْنَ", "translation_urdu_kanzul_iman": "وہ جو سود کھاتے ہیں قیامت کے دن نہ کھڑے ہوں گے مگر جیسے کھڑا ہوتا ہے وہ جسے آسیب نے چھو کر مَخبوط بنادیا ہو یہ اس لئے کہ انہوں نے کہا بیع بھی تو سود ہی کے مانند ہے اور  اللہ  نے حلال کیا بیع اور حرام کیا سود تو جسے اس کے رب کے پاس سے نصیحت آئی اور وہ باز رہا تو اسے حلال ہے جو پہلے لے چکا اور اس کا کام خدا کے سپرد ہے اور جو اب ایسی حرکت کرے گا تو وہ دوزخی ہے وہ اس میں مدتوں رہیں گے۔", "translation_urdu_kanzul_irfan": "جو لوگ سود کھاتے ہیں  وہ قیامت کے دن نہ کھڑے ہوں  گے مگر اس شخص کے کھڑے ہونے کی طرح جسے آسیب نے چھو کرپاگل بنادیا ہو۔ یہ سزا اس وجہ سے ہے کہ انہوں  نے کہا: خریدوفروخت بھی تو سود ہی کی طرح ہے حالانکہ اللہ  نے خریدوفروخت کو حلال کیا اورسود کو حرام کیا تو جس کے پاس اس کے رب کی طرف سے نصیحت آئی پھر وہ باز آ گیا تو اس کیلئے حلال ہے وہ جو پہلے گزرچکا اور اس کامعاملہ اللہ  کے سپرد ہے اور جودوبارہ ایسی حرکت کریں  گے تو وہ دوزخی ہیں  ، وہ اس میں  مدتوں  رہیں  گے۔", "translation_english": "Those who consume usury (i.e. interest) will not stand up on the Day of Judgement but stand like the one who is possessed by an evil spirit making him insane; this is because they said, 'Trade is in fact also like usury.' And Allah has made trading lawful and has made usury unlawful. Therefore, the one whom advice has come to from his Lord, and he refrained from it, so what he has taken in the past is lawful for him. And his matter is with Allah, and whoever does the same (i.e. continues earning usury) henceforth is the inmate of Hell; they will remain therein for a very long time.", "wisdom_benefit_ur": "سود غریبوں کا خون چوستا ہے، پیداواری صلاحیت کو مارتا ہے اور چند ہاتھوں میں دولت کا ناجائز ارتکاز پیدا کرتا ہے۔", "wisdom_benefit_en": "Usury and predatory interest extract unearned wealth from labor, compound unpayable debt crises, and trigger cyclical systemic crashes."}, {"serial": 54, "id": "cmd_054", "surah_id": 2, "ayah_num": 188, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "prohibition", "title_ur": "ایک دوسرے کا مال ناحق مت کھاؤ اور حکام کو رشوت نہ دو", "title_en": "Do Not Unjustly Consume Wealth or Bribe Officials", "arabic": "وَلَا تَاْكُلُوْۤا اَمْوَالَكُمْ بَیْنَكُمْ بِالْبَاطِلِ وَتُدْلُوْا بِهَاۤ اِلَى الْحُكَّامِ لِتَاْكُلُوْا فَرِیْقًا مِّنْ اَمْوَالِ النَّاسِ بِالْاِثْمِ وَاَنْتُمْ تَعْلَمُوْنَ۠", "translation_urdu_kanzul_iman": "اور آپس میں ایک دوسرے کا مال ناحق نہ کھاؤ اور نہ حاکموں کے پاس ان کا مقدمہ اس لئے پہنچاؤ کہ لوگوں کا کچھ مال ناجائز طور پر کھالو جان بوجھ کر۔", "translation_urdu_kanzul_irfan": "اور آپس میں  ایک دوسرے کا مال ناحق نہ کھاؤ اور نہ حاکموں  کے پاس ان کا مقدمہ اس لئے پہنچاؤ کہ لوگوں  کا کچھ مال ناجائز طور پرجان بوجھ کر کھالو۔", "translation_english": "And do not unfairly consume the wealth of each other, nor take their cases to rulers, in order that you may wrongfully consume a part of other people's wealth knowingly.", "wisdom_benefit_ur": "حرام خوری، غبن اور رشوت ستانی انصاف کو بیچ ڈالتی ہے اور قانون کی حکمرانی کا جنازہ نکال دیتی ہے۔", "wisdom_benefit_en": "Outlaws bribery, graft, and embezzlement, defending administrative justice from corrupt capture by predatory elites."}, {"serial": 55, "id": "cmd_055", "surah_id": 2, "ayah_num": 282, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "command", "title_ur": "جب کسی مقررہ مدت کے لیے ادھار کا لین دین کرو تو اسے لکھ لو", "title_en": "Record Financial Debts & Contracts in Writing", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اِذَا تَدَایَنْتُمْ بِدَیْنٍ اِلٰۤى اَجَلٍ مُّسَمًّى فَاكْتُبُوْهُؕ-وَلْیَكْتُبْ بَّیْنَكُمْ كَاتِبٌۢ بِالْعَدْلِ۪-وَلَا یَاْبَ كَاتِبٌ اَنْ یَّكْتُبَ كَمَا عَلَّمَهُ اللّٰهُ فَلْیَكْتُبْۚ-وَلْیُمْلِلِ الَّذِیْ عَلَیْهِ الْحَقُّ وَلْیَتَّقِ اللّٰهَ رَبَّهٗ وَلَا یَبْخَسْ مِنْهُ شَیْــٴًـاؕ-فَاِنْ كَانَ الَّذِیْ عَلَیْهِ الْحَقُّ سَفِیْهًا اَوْ ضَعِیْفًا اَوْ لَا یَسْتَطِیْعُ اَنْ یُّمِلَّ هُوَ فَلْیُمْلِلْ وَلِیُّهٗ بِالْعَدْلِؕ-وَاسْتَشْهِدُوْا شَهِیْدَیْنِ مِنْ رِّجَالِكُمْۚ-فَاِنْ لَّمْ یَكُوْنَا رَجُلَیْنِ فَرَجُلٌ وَّامْرَاَتٰنِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَدَآءِ اَنْ تَضِلَّ اِحْدٰىهُمَا فَتُذَكِّرَ اِحْدٰىهُمَا الْاُخْرٰىؕ-وَلَا یَاْبَ الشُّهَدَآءُ اِذَا مَا دُعُوْاؕ-وَلَا تَسْــٴَـمُوْۤا اَنْ تَكْتُبُوْهُ صَغِیْرًا اَوْ كَبِیْرًا اِلٰۤى اَجَلِهٖؕ-ذٰلِكُمْ اَقْسَطُ عِنْدَ اللّٰهِ وَاَقْوَمُ لِلشَّهَادَةِ وَاَدْنٰۤى اَلَّا تَرْتَابُوْۤا اِلَّاۤ اَنْ تَكُوْنَ تِجَارَةً حَاضِرَةً تُدِیْرُوْنَهَا بَیْنَكُمْ فَلَیْسَ عَلَیْكُمْ جُنَاحٌ اَلَّا تَكْتُبُوْهَاؕ-وَاَشْهِدُوْۤا اِذَا تَبَایَعْتُمْ۪-وَلَا یُضَآرَّ كَاتِبٌ وَّلَا شَهِیْدٌ۬ؕ-وَاِنْ تَفْعَلُوْا فَاِنَّهٗ فُسُوْقٌۢ بِكُمْؕ-وَاتَّقُوا اللّٰهَؕ-وَیُعَلِّمُكُمُ اللّٰهُؕ-وَاللّٰهُ بِكُلِّ شَیْءٍ عَلِیْمٌ", "translation_urdu_kanzul_iman": "اے ایمان والو جب تم ایک مقرر مدت تک کسی دین کا لین دین کرو تو اسے لکھ لو اور چاہئے کہ تمہارے درمیان کوئی لکھنے والا ٹھیک ٹھیک لکھے اور لکھنے والا لکھنے سے انکار نہ کرے جیسا کہ اسے  اللہ  نے سکھایا ہے تو اسے لکھ دینا چاہئے اور جس پر حق آتا ہے وہ لکھاتا جائے اور  اللہ  سے ڈرے جو اس کا رب ہے اور حق میں سے کچھ رکھ نہ چھوڑے پھر جس پر حق آتا ہے اگر بے عقل یا ناتواں ہو یا لکھا نہ سکے تو اس کا ولی انصاف سے لکھائے، اور دو گواہ کرلو اپنے مَردوں میں سے پھر اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں ایسے گواہ جن کو پسند کروکہ کہیں ان میں ایک عورت بھولے تو اس ایک کو دوسری یاد دلاوے اور گواہ جب بلائے جائیں تو آنے سے انکار نہ کریں اور اسے بھاری نہ جانو کہ دَین چھوٹا ہو یا بڑا اس کی میعاد تک لکھت کرلو یہ  اللہ   کے نزدیک زیادہ انصاف کی بات ہے اوراس میں گواہی خوب ٹھیک رہے گی اور یہ اس سے قریب ہے کہ تمہیں شبہہ نہ پڑے مگر یہ کہ کوئی سردست کا سودا دست بَدست ہو تو اس کے نہ لکھنے کا تم پر گناہ نہیں اور جب خرید و فروخت کرو تو گواہ کرلو اور نہ کسی لکھنے والے کو ضَرر دیا جائے، نہ گواہ کو (یا، نہ لکھنے والا ضَرر دے نہ گواہ) اور جو ایسا کرو تو یہ تمہارا فسق ہوگا اور  اللہ  سے ڈرو اور  اللہ  تمہیں سکھاتا ہے، اور  اللہ  سب کچھ جانتا ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! جب تم ایک مقرر مدت تک کسی قرض کا لین دین کرو تو اسے لکھ لیا کرو اور تمہارے درمیان کسی لکھنے والے کو انصاف کے ساتھ (معاہدہ) لکھنا چاہئے اور لکھنے والا لکھنے سے انکار نہ کرے جیسا کہ اسے اللہ نے سکھایا ہے تو اسے لکھ دینا چاہئے اور جس شخص پر حق لازم آتا ہے وہ لکھاتا جائے اور اللہ سے ڈرے جو اس کا رب ہے اور اس حق میں سے کچھ کمی نہ کرے پھر جس پر حق آتا ہے اگر وہ بے عقل یا کمزور ہو یا لکھوا نہ سکتا ہو تو اس کا ولی انصاف کے ساتھ لکھوا دے اور اپنے مردوں میں سے دو گواہ بنالوپھر اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں ان گواہوں میں سے (منتخب کرلو) جنہیں تم پسند کرو تاکہ (اگر) ان میں سے ایک عورت بھولے تو دوسری اسے یاد دلادے، اور جب گواہوں کو بلایا جائے تو وہ آنے سے انکار نہ کریں اور قرض چھوٹا ہو یا بڑا اسے اس کی مدت تک لکھنے میں اکتاؤ نہیں۔ یہ اللہ کے نزدیک زیادہ انصاف کی بات ہے اوراس میں گواہی خوب ٹھیک رہے گی اور یہ اس سے قریب ہے کہ تم (بعد میں) شک میں نہ پڑو (ہر معاہدہ لکھا کرو) مگر یہ کہ کوئی ہاتھوں ہاتھ سودا ہوجس کا تم آپس میں لین دین کرو تو اس کے نہ لکھنے میں تم پر کوئی حرج نہیں اور جب خرید و فروخت کرو تو گواہ بنالیا کرو اور نہ کسی لکھنے والے کوکوئی نقصان پہنچایا جائے اور نہ گواہ کو (یانہ لکھنے والا کوئی نقصان پہنچائے اور نہ گواہ ) اور اگر تم ایسا کرو گے تو یہ تمہاری نافرمانی ہوگی اور اللہ سے ڈرو اور اللہ تمہیں سکھاتا ہے اور اللہ سب کچھ جانتا ہے۔", "translation_english": "O believers! If you make an agreement of debt for a specified period, so write it down. And a scribe should accurately write (the agreement) between you accurately, and the scribe should not refuse to write in the manner that Allah has taught him, he should therefore write (it). And the liable person (i.e. the debtor) should dictate to him and should fear Allah Who is his Lord, and not omit anything concerning the rights (of those involved); if the debtor is then of low understanding, or incapable, or unable to dictate by himself, his guardian should therefore dictate with justice. And appoint two witnesses from amongst your men; then if two men are not available, so one man and two women; from such witnesses whom you like, so that if one of the women forgets, the other can therefore remind her. And the witnesses must therefore not refuse when called upon to testify. Do not feel it a burden (to write it), whether the debt is small or big; write it down along with its fixed period; this is closer to justice according to Allah, and will be of strong evidence and more likely to prevent doubts amongst yourselves except when it is an instant trade in which the exchange is immediate; so there is no sin upon you for not writing it down. And appoint witnesses when you therefore conclude a contract of buying and selling, and neither the scribe nor the witnesses be subjected to any harm (or the scribe and witness must not cause any harm to anyone else); and if you do so, this would henceforth be a sin on your part. And fear Allah, and Allah teaches you (His rules), and Allah knows everything.", "wisdom_benefit_ur": "معاہدوں کو تحریری شکل دینا بھول چوک، بدنیتی اور عدالتوں کے سالہا سال طویل جھگڑوں سے محفوظ رکھتا ہے۔", "wisdom_benefit_en": "Mandates formal written documentation and witnesses for financial credit, preventing contractual amnesia, ambiguity, and litigation."}, {"serial": 56, "id": "cmd_056", "surah_id": 5, "ayah_num": 1, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "command", "title_ur": "اپنے تمام معاہدوں، وعدوں اور اقرار ناموں کو پورا کرو", "title_en": "Fulfill All Covenants, Contracts & Pledges", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اَوْفُوْا بِالْعُقُوْدِ۬ؕ-اُحِلَّتْ لَكُمْ بَهِیْمَةُ الْاَنْعَامِ اِلَّا مَا یُتْلٰى عَلَیْكُمْ غَیْرَ مُحِـلِّی الصَّیْدِ وَاَنْتُمْ حُرُمٌؕ-اِنَّ اللّٰهَ یَحْكُمُ مَا یُرِیْدُ", "translation_urdu_kanzul_iman": "اے ایمان والو اپنے قول پورے کرو تمہارے لئے حلال ہوئے بے زبان مویشی مگر وہ جو آگے سنایا جائے گا تم کو لیکن شکار حلال نہ سمجھو جب تم احرام میں ہو بیشک  اللہ  حکم فرماتا ہے جو چاہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! تمام عہد پورے کیا کرو۔ تمہارے لئے چوپائے جانور حلال کردیے گئے سوائے ان کے جو (آگے) تمہارے سامنے بیان کئے جائیں  گے لیکن احرام کی حالت میں  شکار حلال نہ سمجھو۔ بیشک اللہ جو چاہتا ہے حکم فرماتا ہے۔", "translation_english": "O believers! Fulfil your promises. Mute animals are made lawful for you (to eat) except that which will be stated to you further on, but do not regard hunting as lawful when you are in the state of Ihraam (the ritual attire for the performance of pilgrimage). Indeed, Allah commands as He wills.", "wisdom_benefit_ur": "معاہدوں کی پاسداری ہر کامیاب معیشت اور مہذب قوم کی ریڑھ کی ہڈی ہے۔ وعدہ خلافی دیوالیہ پن کا پیش خیمہ ہے۔", "wisdom_benefit_en": "Sanctity of contract is the cornerstone of economic predictability; honoring commitments guarantees commercial reliability."}, {"serial": 57, "id": "cmd_057", "surah_id": 4, "ayah_num": 58, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "command", "title_ur": "امانتیں ان کے حقداروں کو واپس پہنچاؤ", "title_en": "Discharge Trusts to Those Entitled to Them", "arabic": "اِنَّ اللّٰهَ یَاْمُرُكُمْ اَنْ تُؤَدُّوا الْاَمٰنٰتِ اِلٰۤى اَهْلِهَاۙ-وَاِذَا حَكَمْتُمْ بَیْنَ النَّاسِ اَنْ تَحْكُمُوْا بِالْعَدْلِؕ-اِنَّ اللّٰهَ نِعِمَّا یَعِظُكُمْ بِهٖؕ-اِنَّ اللّٰهَ كَانَ سَمِیْعًۢا بَصِیْرًا", "translation_urdu_kanzul_iman": "بے شک  اللہ   تمہیں حکم دیتا ہے کہ امانتیں جن کی ہیں انھیں سپرد کرو اور یہ کہ جب تم لوگوں میں فیصلہ کرو تو انصاف کے ساتھ فیصلہ کروبے شک  اللہ   تمہیں کیا ہی خوب نصیحت فرماتا ہے بے شک  اللہ  سنتا دیکھتا ہے ۔", "translation_urdu_kanzul_irfan": "بیشک اللہ  تمہیں  حکم دیتا ہے کہ امانتیں  جن کی ہیں  ان کے سپرد کرو اور یہ کہ جب تم لوگوں  میں  فیصلہ کرو تو انصاف کے ساتھ فیصلہ کرو بیشک اللہ   تمہیں  کیا ہی خوب نصیحت فرماتا ہے، بیشک اللہ  سننے والا ،دیکھنے والا ہے۔", "translation_english": "Indeed, Allah commands you to hand over whatever you hold in trust to their owners, and this; that whenever you judge between people, so judge with justice. Undoubtedly, what excellent advice Allah gives you. Indeed, Allah is All-Hearing, All-Seeing.", "wisdom_benefit_ur": "خواہ وہ مالی امانت ہو، راز ہو یا عوامی عہدہ—امانت کی امانت داری کے ساتھ واپسی ہی امن اور عدل کی ضمانت ہے۔", "wisdom_benefit_en": "Mandates fiduciary fidelity in handling private deposits, corporate assets, public offices, and confidential disclosures."}, {"serial": 58, "id": "cmd_058", "surah_id": 17, "ayah_num": 29, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "command", "title_ur": "نہ ہاتھ گردن سے باندھ لو (کنجوسی) اور نہ بالکل کھلا چھوڑ دو (فضول خرچی)", "title_en": "Neither Be a Miser Nor an Extravagant Spender", "arabic": "وَلَا تَجْعَلْ یَدَكَ مَغْلُوْلَةً اِلٰى عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُوْمًا مَّحْسُوْرًا", "translation_urdu_kanzul_iman": "اور اپنا ہاتھ اپنی گردن سے بندھا ہوا نہ رکھ اور نہ پورا کھول دے کہ تو بیٹھ رہے ملامت کیا ہوا تھکا ہوا۔", "translation_urdu_kanzul_irfan": "اور اپنا ہاتھ اپنی گردن سے بندھا ہوا نہ رکھو اور نہ پورا کھول دو کہ پھر ملامت میں  ، حسرت میں   بیٹھے رہ جاؤ۔", "translation_english": "And do not keep your hand tied to your neck (i.e. do not be miserly) nor open it completely (i.e. do not be wasteful), lest you sit down criticised, tired.", "wisdom_benefit_ur": "بخل انسان کو حقیر بناتا ہے اور اسراف دیوالیہ پن اور قرض کے دلدل میں دھکیلتا ہے۔ میانہ روی ہمیشہ خوشحال رکھتی ہے۔", "wisdom_benefit_en": "Prescribes golden financial equilibrium between paralyzing stinginess and reckless debt-inducing profligacy."}, {"serial": 59, "id": "cmd_059", "surah_id": 2, "ayah_num": 280, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "command", "title_ur": "اگر مقروض تنگی میں ہو تو اسے آسانی تک مہلت دو، اور معاف کر دو تو بہتر ہے", "title_en": "Give Respite or Debt Forgiveness to the Distressed", "arabic": "وَاِنْ كَانَ ذُوْ عُسْرَةٍ فَنَظِرَةٌ اِلٰى مَیْسَرَةٍؕ-وَاَنْ تَصَدَّقُوْا خَیْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَ", "translation_urdu_kanzul_iman": "اور اگر قرضدار تنگی والا ہے تو اسے مہلت دو آسانی تک اور قرض اس پر بالکل چھوڑ دینا تمہارے لئے اور بھلا ہے اگر جانو۔", "translation_urdu_kanzul_irfan": "اور اگر مقروض تنگدست ہو تو اسے آسانی تک مہلت دو اور تمہارا قرض کوصدقہ کردینا تمہارے لئے سب سے بہتر ہے اگر تم جان لو۔", "translation_english": "And if the debtor is in difficulty, so give him respite until it becomes easy (to pay back). And giving up his entire debt is better for you, if you know.", "wisdom_benefit_ur": "مجبور مقروض پر ظلم کرنے کے بجائے مہلت دینا یا معاف کر دینا معاشی خودکشیوں کو روکتا ہے اور اللہ کے فضل کا باعث بنتا ہے۔", "wisdom_benefit_en": "Humanitarian debt restructuring and relief prevent insolvency tragedies, offering second chances to honest but bankrupt borrowers."}, {"serial": 60, "id": "cmd_060", "surah_id": 4, "ayah_num": 10, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "finance", "category_name_ur": "مالی دیانت، تجارت اور عادلانہ لین دین", "category_name_en": "Financial Ethics, Honest Commerce & Fair Dealing", "category_icon": "⚖️", "category_color": "#eab308", "polarity": "prohibition", "title_ur": "یتیموں کا مال ناحق مت کھاؤ، وہ پیٹ میں آگ بھر رہے ہیں", "title_en": "Do Not Unjustly Consume the Wealth of Orphans", "arabic": "اِنَّ الَّذِیْنَ یَاْكُلُوْنَ اَمْوَالَ الْیَتٰمٰى ظُلْمًا اِنَّمَا یَاْكُلُوْنَ فِیْ بُطُوْنِهِمْ نَارًاؕ-وَسَیَصْلَوْنَ سَعِیْرًا۠", "translation_urdu_kanzul_iman": "وہ جو یتیموں کا مال ناحق کھاتے ہیں وہ تو اپنے پیٹ میں نری آ گ بھرتے ہیں اور کوئی دم جاتا ہے کہ بھڑکتے دھڑے (آتش کدے) میں جائیں گے۔", "translation_urdu_kanzul_irfan": "بیشک وہ لوگ جو ظلم کرتے ہوئے یتیموں  کا مال کھاتے ہیں  وہ اپنے پیٹ میں  بالکل آگ بھرتے ہیں  اور عنقریب یہ لوگ بھڑکتی ہوئی آگ میں  جائیں  گے۔", "translation_english": "Those who consume the wealth of orphans unjustly; they are actually only filling their bellies with fire, and soon they will go into a blazing section of the Fire.", "wisdom_benefit_ur": "بے سہارا یتیموں کے ورثے کو کھانا انسانیت سوز جرم ہے جو سخت ترین الٰہی وعید اور دنیاوی بربادی کا سبب بنتا ہے۔", "wisdom_benefit_en": "Strictly defends the assets and inheritance of defenseless minors against predatory guardians and estate embezzlement."}, {"serial": 61, "id": "cmd_061", "surah_id": 17, "ayah_num": 23, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "والدین کے ساتھ حسنِ سلوک کرو، ان کے سامنے 'اف' تک نہ کہو", "title_en": "Treat Parents with Utmost Reverence; Never Say 'Uff'", "arabic": "وَقَضٰى رَبُّكَ اَلَّا تَعْبُدُوْۤا اِلَّاۤ اِیَّاهُ وَبِالْوَالِدَیْنِ اِحْسَانًاؕ-اِمَّا یَبْلُغَنَّ عِنْدَكَ الْكِبَرَ اَحَدُهُمَاۤ اَوْ كِلٰهُمَا فَلَا تَقُلْ لَّهُمَاۤ اُفٍّ وَّلَا تَنْهَرْهُمَا وَقُلْ لَّهُمَا قَوْلًا كَرِیْمًا", "translation_urdu_kanzul_iman": "اور تمہارے رب نے حکم فرمایا کہ اس کے سوا کسی کو نہ پوجو اور ماں  باپ کے ساتھ اچھا سلوک کرو اگر تیرے سامنے ان میں  ایک یا دونوں  بڑھاپے کو پہنچ جائیں  تو ان سے ہُوں  نہ کہنا اور انہیں  نہ جھڑکنا اور ان سے تعظیم کی بات کہنا ۔", "translation_urdu_kanzul_irfan": "اور تمہارے رب نے حکم فرمایا کہ اس کے سوا کسی کی عبادت نہ کرو اور ماں   باپ کے ساتھ اچھا سلوک کرو۔ اگر تیرے سامنے ان میں   سے کوئی ایک یا دونوں   بڑھاپے کو پہنچ جائیں   تو ان سے اُف تک نہ کہنا اور انہیں   نہ جھڑکنا اور ان سے خوبصورت ، نرم بات کہنا۔", "translation_english": "And your Lord has commanded not to worship anyone except Him, and treat parents with goodness; if one of them or both reach old age in front of you, so, do not say (even) 'Ugh' to them and do not scold them, and speak to them words of respect.", "wisdom_benefit_ur": "بڑھاپے میں والدین کی خدمت ان کی قربانیوں کا حق ہے۔ جھڑکنا یا اکتاہٹ ظاہر کرنا اولاد کو اخلاقی پستی میں گراتا ہے۔", "wisdom_benefit_en": "Forbids the slightest verbal irritation or sigh ('Uff') before elderly parents, safeguarding their emotional vulnerability and dignity."}, {"serial": 62, "id": "cmd_062", "surah_id": 17, "ayah_num": 24, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "والدین کے آگے عاجزی کا بازو جھکاؤ اور ان کے لیے رحمت کی دعا کرو", "title_en": "Lower to Parents the Wing of Humility & Mercy", "arabic": "وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّیٰنِیْ صَغِیْرًاؕ", "translation_urdu_kanzul_iman": "اور ان کے لیے عاجزی کا بازو بچھا نرم دلی سے اور عرض کر کہ اے میرے رب تو ان دونوں  پر رحم کر جیسا کہ ان دونوں  نے مجھے چھٹپن میں  پالا۔", "translation_urdu_kanzul_irfan": "اور ان کے لیے نرم دلی سے عاجزی کا بازو جھکا کر رکھ اور دعا کر کہ اے میرے رب! تو ان دونوں   پر رحم فرما جیسا ان دونوں   نے مجھے بچپن میں   پالا۔", "translation_english": "And spread for them the arm of humbleness with a soft heart, and request humbly that 'O my Lord, have mercy on them both, just as they brought me up in my childhood.'", "wisdom_benefit_ur": "جیسے بچپن میں والدین نے بے بس بچے کو پالا، اسی طرح بڑھاپے میں عاجزی اور محبت سے ان کے لیے شفیق بننا فرض ہے۔", "wisdom_benefit_en": "Reciprocates infant caregiving through adult filial humility, praying for their divine mercy and providing compassionate shelter."}, {"serial": 63, "id": "cmd_063", "surah_id": 31, "ayah_num": 14, "surah_name_en": "Luqman", "surah_name_ar": "لُقْمٰن", "surah_name_roman": "Luqman", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "ماں کی مشقتوں کو پہچانو جس نے تکلیف پر تکلیف سہہ کر جنا اور دودھ پلایا", "title_en": "Recognize the Heroic Sacrifices of Mothers", "arabic": "وَوَصَّیْنَا الْاِنْسَانَ بِوَالِدَیْهِۚ-حَمَلَتْهُ اُمُّهٗ وَهْنًا عَلٰى وَهْنٍ وَّفِصٰلُهٗ فِیْ عَامَیْنِ اَنِ اشْكُرْ لِیْ وَلِوَالِدَیْكَؕ-اِلَیَّ الْمَصِیْرُ", "translation_urdu_kanzul_iman": "اور ہم نے آدمی کو اس کے ماں  باپ کے بارے میں  تاکید فرمائی اُس کی ماں  نے اُسے پیٹ میں  رکھا کمزوری پر کمزوری جھیلتی ہوئی اور اس کا دودھ چھوٹنا دو برس میں  ہے یہ کہ حق مان میرا اور اپنے ماں  باپ کا آخر مجھی تک آنا ہے۔", "translation_urdu_kanzul_irfan": "اور ہم نے آدمی کو اس کے ماں   باپ کے بارے میں   تاکید فرمائی۔ اس کی ماں   نے کمزوری پر کمزوری برداشت کرتے ہوئے اسے پیٹ میں   اٹھائے رکھا اور اس کا دودھ چھڑانے کی مدت دو سال میں   ہے کہ میرا اور اپنے والدین کا شکرادا کرو۔ میری ہی طرف لوٹنا ہے۔", "translation_english": "And We emphasised upon man concerning his parents; his mother carried him in the womb, undergoing weakness upon weakness, and his suckling is up to two years, so, be thankful to Me and to your parents. In the end, return is towards only Me.", "wisdom_benefit_ur": "حمل، ولادت اور دو سال دودھ پلانے کی بے لوث قربانیوں کا اعتراف ماں کے تقدس اور معاشرتی تکریم کی بنیاد ہے۔", "wisdom_benefit_en": "Celebrates maternal gestation, birth travail, and prolonged lactation, establishing the paramount moral duty of maternal veneration."}, {"serial": 64, "id": "cmd_064", "surah_id": 30, "ayah_num": 21, "surah_name_en": "Ar Rum", "surah_name_ar": "اَلرُّوْم", "surah_name_roman": "Ar Rum", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "ازدواجی زندگی کو محبت، سکون اور رحمت کی بنیاد پر قائم کرو", "title_en": "Anchor Marriage in Mutual Tranquility, Love & Mercy", "arabic": "وَمِنْ اٰیٰتِهٖۤ اَنْ خَلَقَ لَكُمْ مِّنْ اَنْفُسِكُمْ اَزْوَاجًا لِّتَسْكُنُوْۤا اِلَیْهَا وَجَعَلَ بَیْنَكُمْ مَّوَدَّةً وَّرَحْمَةًؕ-اِنَّ فِیْ ذٰلِكَ لَاٰیٰتٍ لِّقَوْمٍ یَّتَفَكَّرُوْنَ", "translation_urdu_kanzul_iman": "اور اس کی نشانیوں  سے ہے کہ تمہارے لئے تمہاری ہی جنس سے جوڑے بنائے کہ اُن سے آرام پاؤ اور تمہارے آپس میں  محبت اور رحمت رکھی بے شک اس میں  نشانیاں  ہیں  دھیان کرنے والوں  کے لئے۔", "translation_urdu_kanzul_irfan": "اور اس کی نشانیوں   سے ہے کہ اس نے تمہارے لئے تمہاری ہی جنس سے جوڑے بنائے تاکہ تم ان کی طرف آرام پاؤ اور تمہارے درمیان محبت اور رحمت رکھی۔ بے شک ا س میں   غوروفکر کرنے والوں   کیلئے نشانیاں   ہیں  ۔", "translation_english": "And amongst His signs is that He created spouses for you from yourselves for you to gain comfort in them and placed love and mercy between yourselves; indeed, in this are signs for the people who ponder.", "wisdom_benefit_ur": "نکاح جنسی تسکین سے بڑھ کر باہمی سکون، دلی محبت اور باہمی رحمت کا رشتہ ہے جو مستحکم خاندان کی بنیاد ہے۔", "wisdom_benefit_en": "Defines marital union as a haven of psychological tranquility (Sakinah), affection (Mawaddah), and empathy (Rahmah)."}, {"serial": 65, "id": "cmd_065", "surah_id": 4, "ayah_num": 19, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "عورتوں کے ساتھ خوش اسلوبی اور بھلے طریقے سے زندگی بسر کرو", "title_en": "Live with Spouses in Honorable Kindness", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا یَحِلُّ لَكُمْ اَنْ تَرِثُوا النِّسَآءَ كَرْهًاؕ-وَلَا تَعْضُلُوْهُنَّ لِتَذْهَبُوْا بِبَعْضِ مَاۤ اٰتَیْتُمُوْهُنَّ اِلَّاۤ اَنْ یَّاْتِیْنَ بِفَاحِشَةٍ مُّبَیِّنَةٍۚ-وَعَاشِرُوْهُنَّ بِالْمَعْرُوْفِۚ-فَاِنْ كَرِهْتُمُوْهُنَّ فَعَسٰۤى اَنْ تَكْرَهُوْا شَیْــٴًـا وَّیَجْعَلَ اللّٰهُ فِیْهِ خَیْرًا كَثِیْرًا", "translation_urdu_kanzul_iman": "اے ایمان والو تمہیں حلال نہیں کہ عورتوں کے وارث بن جاؤ زبردستی اور عورتوں کو روکو نہیں اس نیت سے کہ جو مہر ان کو دیا تھا اس میں سے کچھ لے لو مگر اس صورت میں کہ صریح بے حیا ئی کا کام کریں اور ان سے اچھا برتاؤ کرو پھر اگر وہ تمہیں پسند نہ آئیں تو قریب ہے کہ کوئی چیز تمہیں ناپسند ہو اور  اللہ  اس میں بہت بھلائی رکھے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! تمہارے لئے حلال نہیں  کہ تم زبردستی عورتوں  کے وارث بن جاؤ اور عورتوں  کو اس نیت سے روکو نہیں  کہ جو مہر تم نے انہیں  دیا تھا اس میں  سے کچھ لے لو سوائے اس صورت کے کہ وہ کھلی بے حیا ئی کا ارتکاب کریں  اور ان کے ساتھ اچھے طریقے سے گزر بسر کرو پھر اگر تمہیں  وہ ناپسند ہوں  تو ہوسکتا ہے کہ کوئی چیز تمہیں  ناپسند ہو اور اللہ  اس میں  بہت بھلائی رکھ دے۔", "translation_english": "O believers! It is not lawful for you to become the heirs of women by force, and do not detain women with the intention of taking away a part of the dowry you gave them, unless they commit blatant shamelessness. And deal with them kindly, if you do not then like them, it is therefore likely that you dislike a thing in which Allah has placed much good.", "wisdom_benefit_ur": "بیوی پر ظلم، بدسلوکی یا زبردستی پابندیاں لگانا ممنوع ہے۔ چھوٹی باتوں کو نظر انداز کر کے حسنِ سلوک رکھنا چاہیے۔", "wisdom_benefit_en": "Outlaws domestic abuse, emotional coercion, and misogynistic mistreatment, commanding gracious and fair cohabitation."}, {"serial": 66, "id": "cmd_066", "surah_id": 24, "ayah_num": 30, "surah_name_en": "An Noor", "surah_name_ar": "اَلنُّوْر", "surah_name_roman": "An Noor", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "مرد اپنی نگاہیں نیچی رکھیں اور اپنی شرمگاہوں کی حفاظت کریں", "title_en": "Men Must Lower Their Gaze & Guard Modesty", "arabic": "قُلْ لِّلْمُؤْمِنِیْنَ یَغُضُّوْا مِنْ اَبْصَارِهِمْ وَیَحْفَظُوْا فُرُوْجَهُمْؕ-ذٰلِكَ اَزْكٰى لَهُمْؕ-اِنَّ اللّٰهَ خَبِیْرٌۢ بِمَا یَصْنَعُوْنَ", "translation_urdu_kanzul_iman": "مسلمان مردوں  کو حکم دو اپنی نگاہیں  کچھ نیچی رکھیں  اور اپنی شرمگاہوں  کی حفاظت کریں  یہ ان کے لیے بہت ستھرا ہے بیشک   اللہ  کو ان کے کاموں  کی خبر ہے۔", "translation_urdu_kanzul_irfan": "مسلمان مردوں   کو حکم دو کہ اپنی نگاہیں   کچھ نیچی رکھیں   اور اپنی شرمگاہوں   کی حفاظت کریں  ، یہ ان کے لیے زیادہ پاکیزہ ہے، بیشک  اللہ  ان کے کاموں   سے خبردار ہے۔", "translation_english": "Command the Muslim men to keep their gaze somewhat low and protect their private parts; this is much purer for them. Indeed, Allah is Aware of their actions.", "wisdom_benefit_ur": "نظریں جھکانا جنسی بے راہ روی، ہوس اور دماغی خلفشار سے بچاتا ہے اور روح کو پاکیزہ اور پروقار رکھتا ہے۔", "wisdom_benefit_en": "Visual discipline protects against hyper-sexualized mental distraction, voyeurism, and moral degeneration, preserving chastity."}, {"serial": 67, "id": "cmd_067", "surah_id": 24, "ayah_num": 31, "surah_name_en": "An Noor", "surah_name_ar": "اَلنُّوْر", "surah_name_roman": "An Noor", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "command", "title_ur": "عورتیں اپنی نگاہیں نیچی رکھیں اور اپنی زینت کو چھپائیں", "title_en": "Women Must Lower Their Gaze & Observe Modesty", "arabic": "وَقُلْ لِّلْمُؤْمِنٰتِ یَغْضُضْنَ مِنْ اَبْصَارِهِنَّ وَیَحْفَظْنَ فُرُوْجَهُنَّ وَلَا یُبْدِیْنَ زِیْنَتَهُنَّ اِلَّا مَا ظَهَرَ مِنْهَا وَلْیَضْرِبْنَ بِخُمُرِهِنَّ عَلٰى جُیُوْبِهِنَّ۪-وَلَا یُبْدِیْنَ زِیْنَتَهُنَّ اِلَّا لِبُعُوْلَتِهِنَّ اَوْ اٰبَآىٕهِنَّ اَوْ اٰبَآءِ بُعُوْلَتِهِنَّ اَوْ اَبْنَآىٕهِنَّ اَوْ اَبْنَآءِ بُعُوْلَتِهِنَّ اَوْ اِخْوَانِهِنَّ اَوْ بَنِیْۤ اِخْوَانِهِنَّ اَوْ بَنِیْۤ اَخَوٰتِهِنَّ اَوْ نِسَآىٕهِنَّ اَوْ مَا مَلَكَتْ اَیْمَانُهُنَّ اَوِ التّٰبِعِیْنَ غَیْرِ اُولِی الْاِرْبَةِ مِنَ الرِّجَالِ اَوِ الطِّفْلِ الَّذِیْنَ لَمْ یَظْهَرُوْا عَلٰى عَوْرٰتِ النِّسَآءِ۪-وَلَا یَضْرِبْنَ بِاَرْجُلِهِنَّ لِیُعْلَمَ مَا یُخْفِیْنَ مِنْ زِیْنَتِهِنَّؕ-وَتُوْبُوْۤا اِلَى اللّٰهِ جَمِیْعًا اَیُّهَ الْمُؤْمِنُوْنَ لَعَلَّكُمْ تُفْلِحُوْنَ", "translation_urdu_kanzul_iman": "اور مسلمان عورتوں  کو حکم دو اپنی نگاہیں  کچھ نیچی رکھیں  اور اپنی پارسائی کی حفاظت کریں  اور اپنا بناؤ نہ دکھائیں  مگر جتنا خود ہی ظاہر ہے اور دوپٹے اپنے گریبانوں  پر ڈالے رہیں  اور اپنا سنگار ظاہر نہ کریں  مگر اپنے شوہروں  پر یا اپنے باپ یا شوہروں  کے باپ یا اپنے بیٹے یا شوہروں  کے بیٹے یا اپنے بھائی یا اپنے بھتیجے یا اپنے بھانجے یا اپنے دین کی عورتیں  یا اپنی کنیزیں  جو اپنے ہاتھ کی مِلک ہوں  یا نوکر بشرطیکہ شہوت والے مرد نہ ہوں  یا وہ بچے جنہیں  عورتوں  کی شرم کی چیزوں  کی خبر نہیں  اور زمین پر پاؤں  زور سے نہ رکھیں  کہ جانا جائے ان کا چھپا ہوا سنگار اور   اللہ  کی طرف توبہ کرو اے مسلمانو سب کے سب اس امید پر کہ تم فلاح پاؤ۔", "translation_urdu_kanzul_irfan": "اور مسلمان عورتوں   کو حکم دو کہ وہ اپنی نگاہیں   کچھ نیچی رکھیں   اور اپنی پارسائی کی حفاظت کریں   اور اپنی زینت نہ دکھائیں   مگر جتنا (بدن کاحصہ) خود ہی ظاہر ہے اور وہ اپنے دوپٹے اپنے گریبانوں   پر ڈالے رکھیں   اور اپنی زینت ظاہر نہ کریں مگر اپنے شوہروں   پر یا اپنے باپ یا شوہروں   کے باپ یا اپنے بیٹوں   یا شوہروں   کے بیٹے یا اپنے بھائیوں   یا اپنے بھتیجوں   یا اپنے بھانجوں   یا اپنی (مسلمان) عورتوں   یا اپنی کنیزوں   پر جو ان کی ملکیت ہوں   یامردوں   میں   سے وہ نوکر جو شہوت والے نہ ہوں  یا وہ بچے جنہیں   عورتوں   کی شرم کی چیزوں   کی خبر نہیں   اور زمین پر اپنے پاؤں   اس لئے زور سے نہ ماریں   کہ ان کی اس زینت کا پتہ چل جائے جو انہوں   نے چھپائی ہوئی ہے اور اے مسلمانو! تم سب  اللہ  کی طرف توبہ کرو اس امید پر کہ تم فلاح پاؤ۔", "translation_english": "And command the Muslim women to keep their gaze slightly low, and to protect their chastity, and not to reveal their adornment except what is apparent itself, and to keep the head-covering wrapped over their bosoms, and not to reveal their adornment except to their own husbands, or fathers, or husbands' fathers; or their own sons or their husbands' sons; or their brothers or their brothers' sons or sisters' sons; or women of their own religion, or the handmaids whom they possess, or servants provided that they are not men of carnal desire, or such children who do not yet know women's private aspects of intimacy, and not to stamp their feet forcibly on the ground in order that their hidden adornment be known. And O Muslims! All of you turn towards Allah in repentance, in the hope of attaining success.", "wisdom_benefit_ur": "حیا اور عفت خواتین کو جنسی اشیاء سمجھے جانے سے بچا کر ان کے احترام اور ذاتی وقار کو تحفظ فراہم کرتی ہے۔", "wisdom_benefit_en": "Modesty shields women from predatory male objectification, elevating their social stature and safeguarding personal boundaries."}, {"serial": 68, "id": "cmd_068", "surah_id": 17, "ayah_num": 32, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "prohibition", "title_ur": "زنا کے قریب بھی مت جاؤ، بیشک وہ کھلی بے حیائی اور برا راستہ ہے", "title_en": "Do Not Even Approach Unlawful Sexual Relations (Zina)", "arabic": "وَلَا تَقْرَبُوا الزِّنٰۤى اِنَّهٗ كَانَ فَاحِشَةًؕ-وَسَآءَ سَبِیْلًا", "translation_urdu_kanzul_iman": "اور بدکاری کے پاس نہ جاؤبیشک وہ بے حیائی ہے اور بہت ہی بُری راہ۔", "translation_urdu_kanzul_irfan": "اور بدکاری کے پاس نہ جاؤ بیشک وہ بے حیائی ہے اور بہت ہی برا راستہ ہے۔", "translation_english": "And do not even go near Zina (fornication/adultery i.e. unlawful  intercourse); it is indeed shamelessness, and a very evil way.", "wisdom_benefit_ur": "زنا خاندانی نظام کو برباد کرتا ہے، نسلوں کا نسب مشکوک بناتا ہے اور خطرناک جنسی امراض (ایڈز وغیرہ) کا سبب بنتا ہے۔", "wisdom_benefit_en": "Prohibits not merely illicit intercourse, but all proximal gateways leading to it, preventing lineage chaos and STD epidemics."}, {"serial": 69, "id": "cmd_069", "surah_id": 17, "ayah_num": 31, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "prohibition", "title_ur": "اپنی اولاد کو مفلسی کے خوف سے قتل مت کرو، ہم انہیں بھی رزق دیتے ہیں اور تمہیں بھی", "title_en": "Do Not Kill Your Children for Fear of Poverty", "arabic": "وَلَا تَقْتُلُـوْۤا اَوْلَادَكُمْ خَشْیَةَ اِمْلَاقٍؕ-نَحْنُ نَرْزُقُهُمْ وَاِیَّاكُمْؕ-اِنَّ قَتْلَهُمْ كَانَ خِطْاً كَبِیْرًا", "translation_urdu_kanzul_iman": "اور اپنی اولاد کو قتل نہ کرو مفلسی کے ڈر سے ہم تمہیں  بھی اور انہیں  بھی روزی دیں  گے بیشک ان کا قتل بڑی خطا ہے۔", "translation_urdu_kanzul_irfan": "اور غربت کے ڈر سے اپنی اولاد کو قتل نہ کرو، ہم انہیں   بھی رزق دیں   گے اور تمہیں   بھی، بیشک انہیں   قتل کرناکبیرہ گناہ ہے۔", "translation_english": "And do not kill your children due to the fear of poverty; We will provide sustenance to them and to you as well, indeed, killing them is a big mistake.", "wisdom_benefit_ur": "معاشی تنگی کے ڈر سے نومولود بچوں (یا لڑکیوں) کا قتل یا اسقاطِ حمل سنگدلی ہے۔ رزق کا ضامن صرف اور صرف ربِ کائنات ہے۔", "wisdom_benefit_en": "Bans infanticide and economically-driven abortions of viable life, affirming that divine providence sustains every newborn soul."}, {"serial": 70, "id": "cmd_070", "surah_id": 2, "ayah_num": 231, "surah_name_en": "Al Baqarah", "surah_name_ar": "اَلْبَقَرَة", "surah_name_roman": "Al Baqarah", "category_id": "family", "category_name_ur": "والدین، خاندان اور عفت و پاکدامنی", "category_name_en": "Family, Parents & Gender Modesty", "category_icon": "👨‍👩‍👧", "category_color": "#ec4899", "polarity": "prohibition", "title_ur": "عورتوں کو دکھ دینے یا ان کا حق مارنے کے لیے روک کر مت رکھو", "title_en": "Do Not Retain Women Unfairly to Harm Them", "arabic": "وَاِذَا طَلَّقْتُمُ النِّسَآءَ فَبَلَغْنَ اَجَلَهُنَّ فَاَمْسِكُوْهُنَّ بِمَعْرُوْفٍ اَوْ سَرِّحُوْهُنَّ بِمَعْرُوْفٍ ۪-وَّلَا تُمْسِكُوْهُنَّ ضِرَارًا لِّتَعْتَدُوْاۚ-وَمَنْ یَّفْعَلْ ذٰلِكَ فَقَدْ ظَلَمَ نَفْسَهٗؕ-وَلَا تَتَّخِذُوْۤا اٰیٰتِ اللّٰهِ هُزُوًا٘-وَّاذْكُرُوْا نِعْمَتَ اللّٰهِ عَلَیْكُمْ وَمَاۤ اَنْزَلَ عَلَیْكُمْ مِّنَ الْكِتٰبِ وَالْحِكْمَةِ یَعِظُكُمْ بِهٖؕ-وَاتَّقُوا اللّٰهَ وَاعْلَمُوْۤا اَنَّ اللّٰهَ بِكُلِّ شَیْءٍ عَلِیْمٌ۠", "translation_urdu_kanzul_iman": "اور جب تم عورتوں کو طلاق دو اور ان کی میعاد آلگے تو اس وقت تک یا بھلائی کے ساتھ روک لو یا نکوئی  کے ساتھ چھوڑ دو اور انہیں ضرر دینے کے لئے روکنا نہ ہو کہ حد سے بڑھو اور جو ایسا کرے وہ اپنا ہی نقصان کرتا ہے اور  اللہ  کی آیتوں کو ٹھٹھا نہ بنالو اور یاد کرو  اللہ  کا احسان جو تم پر ہے اور و ہ جو تم پر کتاب و حکمت اتاری تمہیں نصیحت دینے کو اور  اللہ  سے ڈرتے رہو اور جان رکھو کہ  اللہ   سب کچھ جانتا ہے۔", "translation_urdu_kanzul_irfan": "اور جب تم عورتوں  کو طلاق دو اوروہ اپنی (عدت کی اختتامی) مدت (کے قریب) تک پہنچ جائیں  تو اس وقت انہیں  اچھے طریقے سے روک لو یا اچھے طریقے سے چھوڑ دو اور انہیں  نقصان پہنچانے کے لئے نہ روک رکھو تاکہ تم(ان پر) زیادتی کرو اور جو ایسا کرے تو اس نے اپنی جان پر ظلم کیا اور اللہ  کی آیتوں  کو ٹھٹھا مذاق نہ بنالو اور اپنے اوپر اللہ   کا احسان یاد کرو اور اس نے تم پر جو کتاب اور حکمت اتاری ہے (اسے یاد کرو) اس کے ذریعے وہ تمہیں  نصیحت فرماتا ہے اور اللہ  سے ڈرتے رہو اور جان رکھو کہ اللہ   سب کچھ جاننے والا ہے۔", "translation_english": "And when you divorce women and their prescribed period (i.e. 'Iddah) is close to completion, so either keep them on good terms within this period or release them with kindness. And keeping them should not be for the purpose of hurting them, that you may transgress the limits; and he who does so harms himself only. And do not make the verses of Allah an object of mockery, and remember the favour of Allah bestowed upon you and that (favour) sent down to you; the Book (i.e. the Qur'aan) and wisdom (i.e. the Sunnah) for your guidance. And keep fearing Allah, and know that Allah knows everything.", "wisdom_benefit_ur": "طلاق کے معاملات میں عورت کو لٹکائے رکھنا یا تنگ کر کے اس کا حق مہر ہڑپنا سنگین گناہ اور ظلم ہے۔", "wisdom_benefit_en": "Prevents male legal obstructionism during marital dissolution, outlawing holding women in limbo to extort financial concessions."}, {"serial": 71, "id": "cmd_071", "surah_id": 4, "ayah_num": 135, "surah_name_en": "An Nisa", "surah_name_ar": "اَلنِّسَآء", "surah_name_roman": "An Nisa", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "command", "title_ur": "انصاف پر مضبوطی سے جم جاؤ، خواہ اپنے، والدین یا رشتہ داروں کے خلاف ہی کیوں نہ ہو", "title_en": "Stand Firmly for Justice Even Against Yourselves", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا كُوْنُوْا قَوّٰمِیْنَ بِالْقِسْطِ شُهَدَآءَ لِلّٰهِ وَلَوْ عَلٰۤى اَنْفُسِكُمْ اَوِ الْوَالِدَیْنِ وَالْاَقْرَبِیْنَۚ-اِنْ یَّكُنْ غَنِیًّا اَوْ فَقِیْرًا فَاللّٰهُ اَوْلٰى بِهِمَا ؕ فَلَا تَتَّبِعُوا الْهَوٰۤى اَنْ تَعْدِلُوْاۚ-وَاِنْ تَلْوٗۤا اَوْ تُعْرِضُوْا فَاِنَّ اللّٰهَ كَانَ بِمَا تَعْمَلُوْنَ خَبِیْرًا", "translation_urdu_kanzul_iman": "اے ایمان والو انصاف پر خوب قائم ہوجاؤ  اللہ  کے لیے گواہی دیتے چاہے اس میں تمہارا اپنا نقصان ہو یا ماں باپ کا یا رشتہ داروں کا جس پر گواہی دو وہ غنی ہو یا فقیر ہو بہرحال  اللہ  کو اس کا سب سے زیادہ اختیار ہے تو خواہش کے پیچھے نہ جاؤ کہ حق سے الگ پڑواور اگر تم ہیر پھیر کرو یا منہ پھیرو تو  اللہ  کو تمہارے کاموں کی خبر ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! اللہ  کے لئے گواہی دیتے ہوئے انصاف پر خوب قائم ہوجاؤ چاہے تمہارے اپنے یا والدین یا رشتے داروں  کے خلاف ہی (گواہی) ہو۔ جس پر گواہی دو وہ غنی ہو یا فقیر بہرحال اللہ  ان کے زیادہ قریب ہے تو (نفس کی) خواہش کے پیچھے نہ چلوکہ عدل نہ کرو۔ اگر تم ہیر پھیر کرو یا منہ پھیرو تو اللہ  کو تمہارے کاموں  کی خبر ہے۔", "translation_english": "O believers! Become firm in standing for justice (whilst) giving testimony for the sake of Allah, even if there is loss in it for yourselves, or for (your) parents, or for (your) relatives; whether the one you testify against is rich or poor; nevertheless, Allah has greater right over it. Do not therefore follow your wishes lest you separate from the truth (i.e. justice), and if you distort (testimony) or turn away (from giving it), so Allah is Aware of your actions.", "wisdom_benefit_ur": "عدل کا نفاذ جب اپنے اور اپنوں پر بھی بغیر رعایت کے ہو، تب ہی معاشرے میں امن، سچی برابری اور قانون کی بالادستی قائم ہوتی ہے۔", "wisdom_benefit_en": "Establishes universal legal impartiality, commanding adherence to absolute truth even when adverse to self-interest, wealth, or kin."}, {"serial": 72, "id": "cmd_072", "surah_id": 5, "ayah_num": 8, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "command", "title_ur": "کسی قوم کی دشمنی تمہیں ناانصافی اور ظلم پر نہ ابھارے", "title_en": "Never Let Hatred of Any People Cause Injustice", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا كُوْنُوْا قَوّٰمِیْنَ لِلّٰهِ شُهَدَآءَ بِالْقِسْطِ٘-وَلَا یَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ عَلٰۤى اَلَّا تَعْدِلُوْاؕ-اِعْدِلُوْا ؕ هُوَ اَقْرَبُ لِلتَّقْوٰى٘-وَاتَّقُوا اللّٰهَؕ-اِنَّ اللّٰهَ خَبِیْرٌۢ بِمَا تَعْمَلُوْنَ", "translation_urdu_kanzul_iman": "اے ایمان والو  اللہ  کے حکم پر خوب قائم ہوجاؤ انصاف کے ساتھ گواہی دیتے اور تم کو کسی قوم کی عداوت اس پر نہ اُبھارے کہ انصاف نہ کرو، انصاف کرو، وہ پرہیزگاری سے زیادہ قریب ہے اور اللہ  سے ڈرو، بیشک  اللہ  کو تمہارے کامو ں کی خبر ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! انصاف کے ساتھ گواہی دیتے ہوئے اللہ  کے حکم پر خوب قائم ہوجاؤ اور تمہیں  کسی قوم کی عداوت اس پر نہ اُبھارے کہ تم انصاف نہ کرو (بلکہ) انصاف کرو، یہ پرہیزگاری کے زیادہ قریب ہے اور اللہ  سے ڈرو، بیشک اللہ  تمہارے تمام اعمال سے خبردار ہے۔", "translation_english": "O believers! Be intensely steadfast in the command of Allah, while giving testimony with justice, and do not let the enmity of any nation provoke you not to do justice, be just; that is closer to piety. And fear Allah; indeed, Allah is Aware of your actions.", "wisdom_benefit_ur": "جنگ، دشمنی اور نظریاتی اختلاف میں بھی فریقِ مخالف کے ساتھ عدل اور اصول پسندی قائم رکھنا اسلام کا عظیم ترین وصف ہے۔", "wisdom_benefit_en": "Transmutes tribal vengeance into objective justice; even bitter adversaries retain universal inalienable rights to fair treatment."}, {"serial": 73, "id": "cmd_073", "surah_id": 5, "ayah_num": 32, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "command", "title_ur": "جس نے ایک بے گناہ انسان کو قتل کیا گویا اس نے پوری انسانیت کو قتل کیا، اور جس نے ایک جان بچائی گویا اس نے سب کو بچایا", "title_en": "Saving One Human Life Is Like Saving All Mankind", "arabic": "مِنْ اَجْلِ ذٰلِكَ ۚ كَتَبْنَا عَلٰى بَنِیْۤ اِسْرَآءِیْلَ اَنَّهٗ مَنْ قَتَلَ نَفْسًۢا بِغَیْرِ نَفْسٍ اَوْ فَسَادٍ فِی الْاَرْضِ فَكَاَنَّمَا قَتَلَ النَّاسَ جَمِیْعًاؕ-وَمَنْ اَحْیَاهَا فَكَاَنَّمَاۤ اَحْیَا النَّاسَ جَمِیْعًاؕ-وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِالْبَیِّنٰتِ٘-ثُمَّ اِنَّ كَثِیْرًا مِّنْهُمْ بَعْدَ ذٰلِكَ فِی الْاَرْضِ لَمُسْرِفُوْنَ", "translation_urdu_kanzul_iman": "اس سبب سے ہم نے بنی اسرائیل پر لکھ دیا کہ جس نے کوئی جان قتل کی بغیر جان کے بدلے یا زمین میں فساد کے تو گویا اس نے سب لوگوں کو قتل کیا اور جس نے ایک جان کو جِلالیا اس نے گویا سب لوگوں کو جلالیا اور بیشک ان کے پاس ہمارے رسول روشن دلیلوں کے ساتھ آئے پھر بیشک ان میں بہت اس کے بعد زمین میں زیادتی کرنے والے ہیں۔", "translation_urdu_kanzul_irfan": "اس کے سبب ہم نے بنی اسرائیل پر لکھ دیا کہ جس نے کسی جان کے بدلے یا زمین میں  فساد پھیلانے کے بدلے کے بغیر کسی شخص کو قتل کیا تو گویا اس نے تمام انسانوں  کو قتل کردیا اور جس نے کسی ایک جان کو (قتل سے بچا کر) زندہ رکھا اس نے گویا تمام انسانوں  کو زندہ رکھا اور بیشک ان کے پاس ہمارے رسول روشن دلیلوں  کے ساتھ آئے پھر بیشک ان میں  سے بہت سے لوگ اس کے بعد (بھی) زمین میں  زیادتی کرنے والے ہیں۔", "translation_english": "For this reason We decreed for the Children of Israel that whoever kills a human without the (legal) retribution of killing or (killed a human) without the retribution for causing turmoil in the earth, it will henceforth be as though he had killed all of mankind. And whosoever gave life to a human (by saving a life), it is as if he had given life to (i.e. saved) all of mankind. And Our Messengers undoubtedly came to them with clear proofs; then, after that, many of them indeed (still) commit excess on the earth.", "wisdom_benefit_ur": "انسانی جان کا تقدس بلا تفریق مذہب و نسل سب کے لیے مساوی ہے۔ ایک جان کا بچانا تمام انسانیت کے تحفظ کے برابر ہے۔", "wisdom_benefit_en": "The ultimate charter of human rights: sanctifies every innocent human life and equates individual protection with universal salvation."}, {"serial": 74, "id": "cmd_074", "surah_id": 17, "ayah_num": 33, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "prohibition", "title_ur": "کسی جان کو جس کا قتل اللہ نے حرام کیا ہے ناحق قتل مت کرو", "title_en": "Do Not Kill Any Soul Unjustly", "arabic": "وَلَا تَقْتُلُوا النَّفْسَ الَّتِیْ حَرَّمَ اللّٰهُ اِلَّا بِالْحَقِّؕ-وَمَنْ قُتِلَ مَظْلُوْمًا فَقَدْ جَعَلْنَا لِوَلِیِّهٖ سُلْطٰنًا فَلَا یُسْرِفْ فِّی الْقَتْلِؕ-اِنَّهٗ كَانَ مَنْصُوْرًا", "translation_urdu_kanzul_iman": "اور کوئی جان جس کی حرمت اللہ نے رکھی ہے ناحق نہ مارو اور جو ناحق مارا جائے تو بیشک ہم نے اس کے وارث کو قابو دیا ہے تو وہ قتل میں  حد سے نہ بڑھے ضرور اس کی مدد ہونی ہے۔", "translation_urdu_kanzul_irfan": "اور جس جان کی اللہ  نے حرمت رکھی ہے اسے ناحق قتل نہ کرو اور جو مظلوم ہوکر مارا جائے تو ہم نے اس کے وارث کو قابو دیا ہے تووہ وارث قتل کا بدلہ لینے میں   حد سے نہ بڑھے۔ بیشک اس کی مدد ہونی ہے۔", "translation_english": "And do not unjustly kill any soul, (the killing) of which Allah has made unlawful. And whoever is slain unjustly; so, We have undoubtedly given the authority (i.e. rights of legal retribution) to his heir. So, he should not cross the limit in slaying; he will definitely be helped (by the Divine Law).", "wisdom_benefit_ur": "ناحق خون بہانا زمین پر فساد اور تباہی کی بدترین شکل ہے جس کی سزا دنیا میں قصاص اور آخرت میں ابدی جہنم ہے۔", "wisdom_benefit_en": "Categorically outlaws homicide and arbitrary killing, defending the bodily integrity of every person under the rule of law."}, {"serial": 75, "id": "cmd_075", "surah_id": 25, "ayah_num": 63, "surah_name_en": "Al Furqan", "surah_name_ar": "اَلْفُرْقَان", "surah_name_roman": "Al Furqan", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "command", "title_ur": "رحمن کے بندے وہ ہیں جو زمین پر عاجزی و انکساری سے چلتے ہیں", "title_en": "The Servants of the Merciful Walk in Humility", "arabic": "وَعِبَادُ الرَّحْمٰنِ الَّذِیْنَ یَمْشُوْنَ عَلَى الْاَرْضِ هَوْنًا وَّاِذَا خَاطَبَهُمُ الْجٰهِلُوْنَ قَالُوْا سَلٰمًا", "translation_urdu_kanzul_iman": "اور رحمٰن کے وہ بندے کہ زمین پر آہستہ چلتے ہیں  اور جب جاہل ان سے بات کرتے ہیں  تو کہتے ہیں  بس سلام۔", "translation_urdu_kanzul_irfan": "اور رحمٰن کے وہ بندے جو زمین پر آہستہ چلتے ہیں اور جب جاہل ان سے بات کرتے ہیں  تو کہتے ہیں  ’’بس سلام‘‘۔", "translation_english": "Those bondsmen of the Most Gracious who walk upon the earth humbly, and when the ignorant address them (rudely), their only response is, 'Salaam' (i.e. a greeting of parting).", "wisdom_benefit_ur": "عاجزی دل سے تکبر کو نکال دیتی ہے، لوگوں میں محبت پیدا کرتی ہے اور انسان کو باوقار، شفیق اور پسندیدہ بناتی ہے۔", "wisdom_benefit_en": "Humility calms the ego, prevents aggressive posturing, and aligns human demeanor with gentleness and emotional peace."}, {"serial": 76, "id": "cmd_076", "surah_id": 17, "ayah_num": 37, "surah_name_en": "Al Isra", "surah_name_ar": "بَنِیْٓ اِسْرَآءِیْل (اَلْاَسْرَاء)", "surah_name_roman": "Al Isra", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "prohibition", "title_ur": "زمین پر اکڑ کر اور غرور سے مت چلو، نہ تم زمین پھاڑ سکتے ہو نہ پہاڑوں کو پہنچ سکتے ہو", "title_en": "Do Not Walk Haughtily; You Cannot Rend the Earth", "arabic": "وَلَا تَمْشِ فِی الْاَرْضِ مَرَحًاۚ-اِنَّكَ لَنْ تَخْرِقَ الْاَرْضَ وَلَنْ تَبْلُغَ الْجِبَالَ طُوْلًا", "translation_urdu_kanzul_iman": "اور زمین میں  اتراتا نہ چل بیشک تو ہر گز زمین نہ چیر ڈالے گا اور ہرگز بلندی میں  پہاڑوں  کو نہ پہنچے گا۔", "translation_urdu_kanzul_irfan": "اور زمین میں   اتراتے ہوئے نہ چل بیشک توہر گز نہ زمین کو پھاڑ دے گا اور نہ ہرگز بلندی میں   پہاڑوں   کو پہنچ جائے گا۔", "translation_english": "And do not walk arrogantly on the earth; undoubtedly, you will indeed never tear the earth apart and will never reach the mountains in height.", "wisdom_benefit_ur": "تکبر انسان کو اندھا، سرکش اور تنہا کر دیتا ہے۔ اپنی اوقات کو یاد رکھنا انسان کو حقیقت پسند اور باشعور رکھتا ہے۔", "wisdom_benefit_en": "Dismantles narcissistic hubris by reminding human beings of their physical limitations in the vast cosmos."}, {"serial": 77, "id": "cmd_077", "surah_id": 31, "ayah_num": 18, "surah_name_en": "Luqman", "surah_name_ar": "لُقْمٰن", "surah_name_roman": "Luqman", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "prohibition", "title_ur": "لوگوں کے سامنے غرور سے گال نہ پھلاؤ اور نہ اتراتے پھرو", "title_en": "Do Not Turn Your Cheek in Scorn or Strut in Pride", "arabic": "وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِی الْاَرْضِ مَرَحًاؕ-اِنَّ اللّٰهَ لَا یُحِبُّ كُلَّ مُخْتَالٍ فَخُوْرٍۚ", "translation_urdu_kanzul_iman": "اور کسی سے بات کرنے میں  اپنا رخسارہ کج نہ کر اور زمین میں  اِتراتا نہ چل بیشک الله کو نہیں  بھاتا کوئی اِتراتا فخر کرتا۔", "translation_urdu_kanzul_irfan": "اورلوگوں   سے بات کرتے وقت اپنا رخسار ٹیڑھا نہ کر اور زمین میں   اکڑتے ہوئے نہ چل، بیشک الله کو ہر اکڑنے والا، تکبر کرنے والا ناپسند ہے۔", "translation_english": "'And do not make your cheek crooked (in arrogance) whilst talking to anyone, nor boastfully walk upon the earth; indeed, Allah does not like any boastful, arrogant person.'", "wisdom_benefit_ur": "لوگوں کو حقیر سمجھ کر منہ بنانا اور اکڑنا نفرت کو جنم دیتا ہے۔ عاجزانہ چہرہ اور میٹھی مسکراہٹ دلوں کو فتح کرتی ہے۔", "wisdom_benefit_en": "Outlaws snobbery and arrogant body language, demanding warm facial expressions and approachable humility in daily interactions."}, {"serial": 78, "id": "cmd_078", "surah_id": 7, "ayah_num": 199, "surah_name_en": "Al Araf", "surah_name_ar": "اَلْاَعْرَاف", "surah_name_roman": "Al Araf", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "command", "title_ur": "معاف کرنا اختیار کرو، بھلائی کا حکم دو اور جاہلوں سے اعراض کرو", "title_en": "Adopt Forgiveness, Enjoin Good, & Turn from Ignorance", "arabic": "خُذِ الْعَفْوَ وَاْمُرْ بِالْعُرْفِ وَاَعْرِضْ عَنِ الْجٰهِلِیْنَ", "translation_urdu_kanzul_iman": "اے محبوب معاف کرنا اختیار کرو اور بھلائی کا حکم دو اور جاہلوں سے منہ پھیرلو ۔", "translation_urdu_kanzul_irfan": "اے حبیب! معاف کرنا اختیار کرو اور بھلائی کا حکم دو اور جاہلوں  سے منہ پھیرلو۔", "translation_english": "And O Beloved; adopt forgiveness, and command good, and turn away from the ignorant.", "wisdom_benefit_ur": "یہ آیت اخلاقِ فاضلہ کا خلاصہ ہے: کمزوریوں پر درگزر، اچھائی کی ترغیب اور جاہلانہ اشتعال انگیزیوں پر وقار سے دامن بچانا۔", "wisdom_benefit_en": "The tri-fold master ethic: cultivate restorative forgiveness, champion universal virtue, and maintain unprovoked immunity to ignorance."}, {"serial": 79, "id": "cmd_079", "surah_id": 5, "ayah_num": 2, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "command", "title_ur": "نیکی اور پرہیزگاری کے کاموں میں ایک دوسرے کی مدد کرو", "title_en": "Cooperate with One Another in Virtue and Piety", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تُحِلُّوْا شَعَآىٕرَ اللّٰهِ وَلَا الشَّهْرَ الْحَرَامَ وَلَا الْهَدْیَ وَلَا الْقَلَآىٕدَ وَلَاۤ ؕمِّیْنَ الْبَیْتَ الْحَرَامَ یَبْتَغُوْنَ فَضْلًا مِّنْ رَّبِّهِمْ وَرِضْوَانًاؕ-وَاِذَا حَلَلْتُمْ فَاصْطَادُوْاؕ-وَلَا یَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ اَنْ صَدُّوْكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ اَنْ تَعْتَدُوْاۘ-وَتَعَاوَنُوْا عَلَى الْبِرِّ وَالتَّقْوٰى ۪-وَلَا تَعَاوَنُوْا عَلَى الْاِثْمِ وَالْعُدْوَانِ۪- وَاتَّقُوا اللّٰهَؕ-اِنَّ اللّٰهَ شَدِیْدُ الْعِقَابِ", "translation_urdu_kanzul_iman": "اے ایمان والو حلال نہ ٹھہرا لو  اللہ  کے نشان اور نہ ادب والے مہینے اور نہ حرم کو بھیجی ہوئی قربانیاں اور نہ جن کے گلے میں علامتیں آویزاں اور نہ ان کا مال آبرو جو عزت والے گھر کا قصد کرکے آئیں اپنے رب کا فضل اور اس کی خوشی چاہتے اور جب احرام سے نکلو تو شکار کرسکتے ہو اور تمہیں کسی قوم کی عداوت کہ انہوں نے تم کو مسجدِ حرام سے روکا تھا زیادتی کرنے پر نہ ابھارے اور نیکی اور پرہیزگاری پر ایک دوسرے کی مدد کرو اور گناہ اور زیادتی پر باہم مدد نہ دو اور اللہ  سے ڈرتے رہو بیشک  اللہ  کا عذاب سخت ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! اللہ  کی نشانیاں  حلال نہ ٹھہرالو اور نہ ادب والے مہینے اور نہ حرم کو بھیجی گئی قربانیاں  اور نہ(حرم میں  لائے جانے والے وہ جانور)جن کے گلے میں  علامتی پٹے ہوں  اور نہ ادب والے گھر کا قصد کرکے آنے والوں  (کے مال و عزت) کوجو اپنے رب کا فضل اور اس کی رضا تلاش کرتے ہیں اور جب احرام سے باہر جاؤ تو شکار کرسکتے ہو اور تمہیں  کسی قوم کی دشمنی اس وجہ سے زیادتی کرنے پر نہ ابھارے کہ انہوں  نے تمہیں  مسجدِ حرام سے روکا تھا اور نیکی اور پرہیزگاری پر ایک دوسرے کی مدد کرو اور گناہ اور زیادتی پر باہم مدد نہ کرو اور اللہ  سے ڈرتے رہو بیشک اللہ  شدید عذاب دینے والا ہے۔", "translation_english": "O believers! Do not make lawful (i.e. dishonour) the symbols of Allah, nor the sacred months, nor the sacrificial animals sent to the Sacred Territory (around Makkah), nor those (animals) bearing signs around their necks, nor the wealth and honour of those travelling towards the Sacred House (Ka'bah) seeking the bounty and contentment of their Lord. And when (you) come out of Ihraam, you may therefore hunt, and let not the enmity of the people, who prevented you from the Sacred Masjid, tempt you to do injustice. And help one another in righteousness and piety, and do not help one another in sin and injustice, and keep fearing Allah; indeed, Allah's punishment is severe.", "wisdom_benefit_ur": "تعلیم، صحت، ماحولیات اور فلاحی کاموں میں اجتماعی تعاون معاشرے کو مضبوط اور فلاحی ریاست بناتا ہے۔", "wisdom_benefit_en": "Mandates civil solidarity and collaborative action in public health, education, welfare, and virtuous community development."}, {"serial": 80, "id": "cmd_080", "surah_id": 5, "ayah_num": 2, "surah_name_en": "Al Maidah", "surah_name_ar": "اَلْمَـآئِدَة", "surah_name_roman": "Al Maidah", "category_id": "justice", "category_name_ur": "عدل و انصاف، حقوقِ انسانی اور عاجزی", "category_name_en": "Justice, Human Rights & Humility", "category_icon": "🏛️", "category_color": "#6366f1", "polarity": "prohibition", "title_ur": "گناہ اور زیادتی و ظلم کے کاموں میں ہرگز تعاون نہ کرو", "title_en": "Do Not Cooperate in Sin, Hostility or Aggression", "arabic": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تُحِلُّوْا شَعَآىٕرَ اللّٰهِ وَلَا الشَّهْرَ الْحَرَامَ وَلَا الْهَدْیَ وَلَا الْقَلَآىٕدَ وَلَاۤ ؕمِّیْنَ الْبَیْتَ الْحَرَامَ یَبْتَغُوْنَ فَضْلًا مِّنْ رَّبِّهِمْ وَرِضْوَانًاؕ-وَاِذَا حَلَلْتُمْ فَاصْطَادُوْاؕ-وَلَا یَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ اَنْ صَدُّوْكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ اَنْ تَعْتَدُوْاۘ-وَتَعَاوَنُوْا عَلَى الْبِرِّ وَالتَّقْوٰى ۪-وَلَا تَعَاوَنُوْا عَلَى الْاِثْمِ وَالْعُدْوَانِ۪- وَاتَّقُوا اللّٰهَؕ-اِنَّ اللّٰهَ شَدِیْدُ الْعِقَابِ", "translation_urdu_kanzul_iman": "اے ایمان والو حلال نہ ٹھہرا لو  اللہ  کے نشان اور نہ ادب والے مہینے اور نہ حرم کو بھیجی ہوئی قربانیاں اور نہ جن کے گلے میں علامتیں آویزاں اور نہ ان کا مال آبرو جو عزت والے گھر کا قصد کرکے آئیں اپنے رب کا فضل اور اس کی خوشی چاہتے اور جب احرام سے نکلو تو شکار کرسکتے ہو اور تمہیں کسی قوم کی عداوت کہ انہوں نے تم کو مسجدِ حرام سے روکا تھا زیادتی کرنے پر نہ ابھارے اور نیکی اور پرہیزگاری پر ایک دوسرے کی مدد کرو اور گناہ اور زیادتی پر باہم مدد نہ دو اور اللہ  سے ڈرتے رہو بیشک  اللہ  کا عذاب سخت ہے۔", "translation_urdu_kanzul_irfan": "اے ایمان والو! اللہ  کی نشانیاں  حلال نہ ٹھہرالو اور نہ ادب والے مہینے اور نہ حرم کو بھیجی گئی قربانیاں  اور نہ(حرم میں  لائے جانے والے وہ جانور)جن کے گلے میں  علامتی پٹے ہوں  اور نہ ادب والے گھر کا قصد کرکے آنے والوں  (کے مال و عزت) کوجو اپنے رب کا فضل اور اس کی رضا تلاش کرتے ہیں اور جب احرام سے باہر جاؤ تو شکار کرسکتے ہو اور تمہیں  کسی قوم کی دشمنی اس وجہ سے زیادتی کرنے پر نہ ابھارے کہ انہوں  نے تمہیں  مسجدِ حرام سے روکا تھا اور نیکی اور پرہیزگاری پر ایک دوسرے کی مدد کرو اور گناہ اور زیادتی پر باہم مدد نہ کرو اور اللہ  سے ڈرتے رہو بیشک اللہ  شدید عذاب دینے والا ہے۔", "translation_english": "O believers! Do not make lawful (i.e. dishonour) the symbols of Allah, nor the sacred months, nor the sacrificial animals sent to the Sacred Territory (around Makkah), nor those (animals) bearing signs around their necks, nor the wealth and honour of those travelling towards the Sacred House (Ka'bah) seeking the bounty and contentment of their Lord. And when (you) come out of Ihraam, you may therefore hunt, and let not the enmity of the people, who prevented you from the Sacred Masjid, tempt you to do injustice. And help one another in righteousness and piety, and do not help one another in sin and injustice, and keep fearing Allah; indeed, Allah's punishment is severe.", "wisdom_benefit_ur": "ظلم، کرپشن اور ناانصافی میں شریک ہونے یا خاموش تماشائی بننے سے انکار کرنا برائی کی زنجیر کو توڑ دیتا ہے۔", "wisdom_benefit_en": "Prohibits complicity in criminal conspiracies, oppression, warmongering, and systemic injustices against any human beings."}]};
